import java.util.List;

// Driver for the exercise. The printed listing leaves the product list as a
// comment, so this file supplies a small list of items and runs the same two
// stream pipelines against it.
public class MarketDemo {

    static class Item {
        private final String name;
        private final double price;
        private final boolean organic;

        Item(String name, double price, boolean organic) {
            this.name = name;
            this.price = price;
            this.organic = organic;
        }

        public String getName() { return name; }
        public double getPrice() { return price; }
        public boolean isOrganic() { return organic; }
    }

    public static void main(String[] args) {
        List<Item> products = List.of(
                new Item("Heirloom Tomatoes", 4.50, true),
                new Item("Sweet Corn", 3.25, false),
                new Item("Goat Cheese", 8.00, true),
                new Item("Apple Cider", 6.75, false),
                new Item("Kale", 2.95, true));

        double totalSum = getTotalPriceSum(products);
        System.out.println("\nTotal inventory value: $" + String.format("%.2f", totalSum));

        double avgOrganic = getAverageOrganicPrice(products);
        System.out.println("Average price (organic items): $" + String.format("%.2f", avgOrganic));
    }

    // 4) Sum all prices using mapToDouble
    public static double getTotalPriceSum(List<Item> products) {
        return products.stream()
                .mapToDouble(Item::getPrice)
                .sum();
    }

    // 5) Average price of organic items
    public static double getAverageOrganicPrice(List<Item> products) {
        return products.stream()
                .filter(Item::isOrganic)
                .mapToDouble(Item::getPrice)
                .average()
                .orElse(0.0);
    }
}

import java.util.List;

public class WeatherApp {
    public static void main(String[] args) {
        List<WeatherEntry> week = List.of(
                new WeatherEntry("2026-07-01", 22.5, "Sunny"),
                new WeatherEntry("2026-07-02", 19.0, "Rainy"),
                new WeatherEntry("2026-07-03", 25.5, "Sunny"),
                new WeatherEntry("2026-07-04", 17.5, "Cloudy"),
                new WeatherEntry("2026-07-05", 16.0, "Rainy"),
                new WeatherEntry("2026-07-06", 28.0, "Sunny"),
                new WeatherEntry("2026-07-07", 21.0, "Cloudy"),
                new WeatherEntry("2026-07-08", 14.5, "Rainy"),
                new WeatherEntry("2026-07-09", 30.5, "Sunny"),
                new WeatherEntry("2026-07-10", 18.5, "Windy"));

        System.out.println("Rainy days:");
        week.stream()
            .filter(entry -> entry.getCondition().equals("Rainy"))
            .forEach(System.out::println);

        System.out.println();
        System.out.println("Temperatures in Fahrenheit:");
        week.stream()
            .map(entry -> entry.getCelsius() * 9 / 5 + 32)
            .forEach(f -> System.out.printf("%.1f F%n", f));

        System.out.println();
        double average = week.stream()
                             .limit(7)
                             .mapToDouble(WeatherEntry::getCelsius)
                             .average()
                             .orElse(0.0);
        System.out.printf("Average for the first week: %.2f C%n", average);
    }
}

import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.stream.Collectors;

// Runnable driver for the pipelines shown in FarmersMarketApp. It carries a small
// stand-in product class and sample data so the sorted, distinct, and limit steps
// can be executed and their output compared.
public class FarmersMarketAppRunner {

    static class Product {
        private final String name;
        private final double price;
        private final boolean organic;
        private final String season;
        private final String vendor;

        Product(String name, double price, boolean organic, String season, String vendor) {
            this.name = name;
            this.price = price;
            this.organic = organic;
            this.season = season;
            this.vendor = vendor;
        }

        public String getName() { return name; }
        public double getPrice() { return price; }
        public boolean isOrganic() { return organic; }
        public String getSeason() { return season; }
        public String getVendor() { return vendor; }
    }

    public static void main(String[] args) {
        List<Product> products = new ArrayList<>();
        products.add(new Product("Heirloom Tomatoes", 4.50, true, "Summer", "Green Acres"));
        products.add(new Product("Sweet Corn", 3.25, true, "Summer", "Green Acres"));
        products.add(new Product("Sourdough Loaf", 6.00, false, "All", "Baker's Lane"));
        products.add(new Product("Blueberry Scone", 3.75, false, "Summer", "Baker's Lane"));
        products.add(new Product("Cinnamon Roll", 4.25, false, "All", "Baker's Lane"));
        products.add(new Product("Apple Turnover", 3.95, false, "Fall", "Baker's Lane"));
        products.add(new Product("Goat Cheese", 7.50, true, "Summer", "Hillside Dairy"));

        List<String> organicSummerNames = products.stream()
                .filter(p -> p.isOrganic() && p.getSeason() != null && p.getSeason().toLowerCase().contains("summer"))
                .sorted(Comparator.comparingDouble(Product::getPrice))
                .map(Product::getName)
                .collect(Collectors.toList());
        System.out.println("\nOrganic summer items by price: " + organicSummerNames);

        List<String> vendors = products.stream()
                .map(Product::getVendor)
                .filter(v -> v != null && !v.isBlank())
                .distinct()
                .sorted()
                .collect(Collectors.toList());
        System.out.println("\nVendors (sorted): " + vendors);

        String vendor = "Baker's Lane";
        List<String> menu = products.stream()
                .filter(p -> p.getVendor() != null && p.getVendor().equalsIgnoreCase(vendor))
                .map(p -> p.getName() + " - $" + String.format("%.2f", p.getPrice()))
                .limit(3)
                .collect(Collectors.toList());
        System.out.println("\n" + vendor + " menu:");
        menu.forEach(System.out::println);

        List<Double> discountedPrices = products.stream()
                .filter(p -> p.getVendor() != null && p.getVendor().equalsIgnoreCase(vendor))
                .map(p -> Math.round(p.getPrice() * 0.90 * 100) / 100.0)
                .collect(Collectors.toList());
        System.out.println("\nDiscounted prices for " + vendor + ": " + discountedPrices);
    }
}

import java.util.Comparator;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.stream.Collectors;

public class TeamStatsApp {
    public static void main(String[] args) {
        List<Player> squad = List.of(
                new Player("Amara", "Forward", 18),
                new Player("Bruno", "Forward", 12),
                new Player("Chen", "Forward", 21),
                new Player("Diego", "Midfielder", 9),
                new Player("Elif", "Midfielder", 14),
                new Player("Farid", "Midfielder", 5),
                new Player("Greta", "Defender", 3),
                new Player("Hugo", "Defender", 6),
                new Player("Ines", "Defender", 1),
                new Player("Jonas", "Goalkeeper", 0));

        Map<String, List<Player>> byPosition = squad.stream()
                .collect(Collectors.groupingBy(Player::getPosition));
        System.out.println("Players grouped by position:");
        byPosition.forEach((position, players) -> System.out.println("  " + position + " -> " + players));

        Optional<Player> topScorer = squad.stream()
                .max(Comparator.comparingInt(Player::getGoals));
        System.out.println("\nTop scorer overall: " + topScorer.orElse(null));

        Map<String, Optional<Player>> topByPosition = squad.stream()
                .collect(Collectors.groupingBy(Player::getPosition,
                        Collectors.maxBy(Comparator.comparingInt(Player::getGoals))));
        System.out.println("\nTop scorer in each position:");
        topByPosition.forEach((position, player) ->
                System.out.println("  " + position + " -> " + player.map(Player::getName).orElse("none")));
