import javafx.scene.control.DatePicker;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;
import javafx.stage.FileChooser;
import javafx.stage.Window;

import java.io.File;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.Comparator;
import java.util.List;

/**
 * Transaction entry/edit/delete for the current month. Categories themselves
 * are managed on the Categories tab; this view just picks from what's there.
 */
public class TransactionEntryView {

    private final CategoryRepository categoryRepository;
    private final TransactionRepository transactionRepository;

    private final ObservableList<Category> categoryOptions = FXCollections.observableArrayList();
    private final ObservableList<Transaction> monthTransactions = FXCollections.observableArrayList();

    public TransactionEntryView(CategoryRepository categoryRepository, TransactionRepository transactionRepository) {
        this.categoryRepository = categoryRepository;
        this.transactionRepository = transactionRepository;
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Transactions", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        categoryOptions.setAll(categoryRepository.findAll());
        refreshTransactions();
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildTransactionManagement());
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildTransactionManagement() {
        DatePicker datePicker = new DatePicker(LocalDate.now());
        ComboBox<TransactionType> typeBox = new ComboBox<>(FXCollections.observableArrayList(TransactionType.values()));
        typeBox.setValue(TransactionType.EXPENSE);
        ComboBox<Category> categoryBox = new ComboBox<>(categoryOptions);
        TextField amountField = new TextField();
        amountField.setPromptText("Amount");
        TextField descriptionField = new TextField();
        descriptionField.setPromptText("Description");
        Label status = new Label();
        status.setWrapText(true);

        TableView<Transaction> table = buildTransactionTable();

        Button saveButton = new Button("Add transaction");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);
        Button importCsvButton = new Button("Import CSV");

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                datePicker.setValue(newSelection.getDate());
                typeBox.setValue(newSelection.getType());
                categoryOptions.stream()
                        .filter(c -> c.getName().equals(newSelection.getCategoryName()))
                        .findFirst()
                        .ifPresent(categoryBox::setValue);
                amountField.setText(newSelection.getAmount().toString());
                descriptionField.setText(newSelection.getDescription());
                saveButton.setText("Update transaction");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add transaction");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            LocalDate date = datePicker.getValue();
            TransactionType type = typeBox.getValue();
            Category category = categoryBox.getValue();
            if (date == null || type == null || category == null) {
                status.setText("Date, type, and category are required.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                String description = descriptionField.getText().trim();
                Transaction selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    transactionRepository.add(date, type, category.getName(), amount, description);
                    status.setText("Added transaction.");
                } else {
                    transactionRepository.update(selected.getId(), date, type, category.getName(), amount, description);
                    status.setText("Updated transaction.");
                }
                table.getSelectionModel().clearSelection();
                amountField.clear();
                descriptionField.clear();
                refreshTransactions();
            } catch (NumberFormatException ex) {
                status.setText("Amount must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            Transaction selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            transactionRepository.remove(selected.getId());
            table.getSelectionModel().clearSelection();
            status.setText("Deleted transaction.");
            refreshTransactions();
        });

        importCsvButton.setOnAction(e -> {
            FileChooser chooser = new FileChooser();
            chooser.setTitle("Import Transactions CSV");
            chooser.getExtensionFilters().add(new FileChooser.ExtensionFilter("CSV files", "*.csv"));
            Window window = ((Node) e.getSource()).getScene().getWindow();
            File file = chooser.showOpenDialog(window);
            if (file == null) {
                return;
            }
            try {
                TransactionCsvImporter.ImportResult result = new TransactionCsvImporter().importFile(file.toPath());
                List<Transaction> imported = transactionRepository.addAll(result.rows());
                status.setText(summarizeImport(imported.size(), result.errors()));
                table.getSelectionModel().clearSelection();
                refreshTransactions();
            } catch (TransactionCsvImportException ex) {
                status.setText("Import failed: " + ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Transaction:"), datePicker, typeBox, categoryBox,
                amountField, descriptionField, saveButton, deleteButton, importCsvButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<Transaction> buildTransactionTable() {
        TableView<Transaction> table = new TableView<>(monthTransactions);

        TableColumn<Transaction, LocalDate> dateCol = new TableColumn<>("Date");
        dateCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getDate()));

        TableColumn<Transaction, TransactionType> typeCol = new TableColumn<>("Type");
        typeCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getType()));

        TableColumn<Transaction, String> categoryCol = new TableColumn<>("Category");
        categoryCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getCategoryName()));

        TableColumn<Transaction, BigDecimal> amountCol = new TableColumn<>("Amount");
        amountCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getAmount()));

        TableColumn<Transaction, String> descriptionCol = new TableColumn<>("Description");
        descriptionCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getDescription()));

        table.getColumns().addAll(dateCol, typeCol, categoryCol, amountCol, descriptionCol);
        return table;
    }

    private String summarizeImport(int imported, List<TransactionCsvImporter.RowError> errors) {
        int total = imported + errors.size();
        StringBuilder summary = new StringBuilder("Imported " + imported + " of " + total + " rows.");
        if (!errors.isEmpty()) {
            summary.append(" ").append(errors.size()).append(" skipped: ");
            errors.stream().limit(3).forEach(err ->
                    summary.append("Row ").append(err.rowNumber()).append(": ").append(err.reason()).append("; "));
            if (errors.size() > 3) {
                summary.append("(+").append(errors.size() - 3).append(" more - see console log)");
            }
        }
        return summary.toString();
    }

    private void refreshTransactions() {
        YearMonth currentMonth = YearMonth.now();
        monthTransactions.setAll(transactionRepository.findAll().stream()
                .filter(t -> YearMonth.from(t.getDate()).equals(currentMonth))
                .sorted(Comparator.comparing(Transaction::getDate))
                .toList());
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class TransactionRepository {

    private final DataPaths dataPaths;
    private final List<Transaction> transactions = new ArrayList<>();
    private long nextId = 1;

    public TransactionRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<Transaction> findAll() {
        return Collections.unmodifiableList(transactions);
    }

    public Transaction add(LocalDate date, TransactionType type, String categoryName,
                            BigDecimal amount, String description) {
        Transaction transaction = new Transaction(nextId++, date, type, categoryName, amount, description);
        transactions.add(transaction);
        persist();
        return transaction;
    }

    public List<Transaction> addAll(List<TransactionDraft> drafts) {
        List<Transaction> added = new ArrayList<>();
        for (TransactionDraft draft : drafts) {
            added.add(new Transaction(nextId++, draft.date(), draft.type(), draft.categoryName(),
                    draft.amount(), draft.description()));
        }
        transactions.addAll(added);
        persist();
        return added;
    }

    public void update(long id, LocalDate date, TransactionType type, String categoryName,
                        BigDecimal amount, String description) {
        for (int i = 0; i < transactions.size(); i++) {
            if (transactions.get(i).getId() == id) {
                transactions.set(i, new Transaction(id, date, type, categoryName, amount, description));
                break;
            }
        }
        persist();
    }

    public void remove(long id) {
        transactions.removeIf(transaction -> transaction.getId() == id);
        persist();
    }

    public void renameCategory(String oldName, String newName) {
        for (int i = 0; i < transactions.size(); i++) {
            Transaction transaction = transactions.get(i);
            if (transaction.getCategoryName().equals(oldName)) {
                transactions.set(i, new Transaction(transaction.getId(), transaction.getDate(), transaction.getType(),
                        newName, transaction.getAmount(), transaction.getDescription()));
            }
        }
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.transactionsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                long id = Long.parseLong(parts[0]);
                LocalDate date = LocalDate.parse(parts[1]);
                TransactionType type = TransactionType.valueOf(parts[2]);
                String categoryName = parts[3];
                BigDecimal amount = new BigDecimal(parts[4]);
                String description = parts[5];
                transactions.add(new Transaction(id, date, type, categoryName, amount, description));
                if (id >= nextId) {
                    nextId = id + 1;
                }
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed transaction line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# id|date|type|categoryName|amount|description");
        for (Transaction transaction : transactions) {
            lines.add(transaction.getId() + "|" + transaction.getDate() + "|" + transaction.getType() + "|"
                    + transaction.getCategoryName() + "|" + transaction.getAmount() + "|" + transaction.getDescription());
        }
        dataPaths.writeLinesAtomic(dataPaths.transactionsFile(), lines);
    }
}

package com.example.finance;

public enum TransactionType {
    INCOME, EXPENSE
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class BudgetServiceTest {

    @Test
    void sumsCategoryTotalsAndLeftoverForTheGivenMonth(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        categoryRepository.add(new Category("Groceries", new BigDecimal("400.00")));
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("3000.00"), "paycheck");
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("120.00"), "shop 1");
        transactionRepository.add(LocalDate.of(2026, 8, 12), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("80.00"), "shop 2");
        // different month, should be excluded
        transactionRepository.add(LocalDate.of(2026, 9, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("999.00"), "next month");

        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(august);
        assertEquals(1, totals.size());
        assertEquals(new BigDecimal("200.00"), totals.get(0).getActual());

        assertEquals(new BigDecimal("3000.00"), budgetService.totalIncome(august));
        assertEquals(new BigDecimal("200.00"), budgetService.totalExpenses(august));
        assertEquals(new BigDecimal("2800.00"), budgetService.leftover(august));
    }

    @Test
    void categoryActualIncludesIncomeTransactionsNotJustExpenses(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        categoryRepository.add(new Category("Paycheck", new BigDecimal("1000.00")));
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Paycheck",
                new BigDecimal("1000.00"), "August paycheck");

        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(august);
        assertEquals(1, totals.size());
        assertEquals(new BigDecimal("1000.00"), totals.get(0).getActual());
        assertTrue(totals.get(0).isIncomeOnly());
    }

    @Test
    void categoryIsNotIncomeOnlyWhenItHasAnyExpenseTransaction(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        categoryRepository.add(new Category("Groceries", new BigDecimal("400.00")));
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);

        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("120.00"), "shop 1");

        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(YearMonth.of(2026, 8));
        assertFalse(totals.get(0).isIncomeOnly());
    }

    @Test
    void isNotOverBudgetWhenActualExactlyMatchesTarget() {
        BudgetService.CategoryTotal total = new BudgetService.CategoryTotal(
                new Category("Groceries", new BigDecimal("400.00")), new BigDecimal("400.00"));
        assertFalse(total.isOverBudget());
    }

    @Test
    void isOverBudgetWhenActualExceedsTarget() {
        BudgetService.CategoryTotal total = new BudgetService.CategoryTotal(
                new Category("Groceries", new BigDecimal("400.00")), new BigDecimal("400.01"));
        assertTrue(total.isOverBudget());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.LocalDate;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CategoryServiceTest {

    private record Fixture(CategoryService service, CategoryRepository categoryRepository,
                            TransactionRepository transactionRepository,
                            RecurringObligationRepository recurringObligationRepository,
                            SavingsGoalRepository savingsGoalRepository) {
    }

    private Fixture newFixture(Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        CategoryService service = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        return new Fixture(service, categoryRepository, transactionRepository, recurringObligationRepository,
                savingsGoalRepository);
    }

    @Test
    void updateRenamesCategoryAndCascadesToTransactions(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Groceries", new BigDecimal("400.00")));
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("50.00"), "shop");

        fixture.service().update("Groceries", new Category("Food", new BigDecimal("450.00")));

        assertEquals("Food", fixture.categoryRepository().findAll().get(0).getName());
        assertTrue(fixture.transactionRepository().findAll().stream()
                .allMatch(t -> t.getCategoryName().equals("Food")));
    }

    @Test
    void deleteRemovesAnUnusedCategory(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Groceries", new BigDecimal("400.00")));

        fixture.service().delete("Groceries");

        assertEquals(0, fixture.categoryRepository().findAll().size());
    }

    @Test
    void deleteRejectsACategoryStillUsedByATransaction(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Groceries", new BigDecimal("400.00")));
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("50.00"), "shop");

        assertThrows(IllegalStateException.class, () -> fixture.service().delete("Groceries"));
        assertEquals(1, fixture.categoryRepository().findAll().size());
    }

    @Test
    void deleteRejectsACategoryStillUsedByAnObligation(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Meal kit", BigDecimal.ZERO));
        fixture.recurringObligationRepository().add(new RecurringObligation("Meal kit",
                new BigDecimal("60.00"), 1, LocalDate.of(2026, 1, 1), null, null));

        assertThrows(IllegalStateException.class, () -> fixture.service().delete("Meal kit"));
    }

    @Test
    void deleteRejectsACategoryStillUsedByASavingsGoal(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.savingsGoalRepository().add(new SavingsGoal("Emergency fund", new BigDecimal("1000.00"), null));

        assertThrows(IllegalStateException.class, () -> fixture.service().delete("Emergency fund"));
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class GoalContributionRepositoryTest {

    @Test
    void updateReplacesTheMatchingContribution(@TempDir Path tempDir) {
        GoalContributionRepository repository = new GoalContributionRepository(new DataPaths(tempDir));
        GoalContribution contribution = repository.add(LocalDate.of(2026, 8, 5), "Emergency fund",
                new BigDecimal("100.00"));

        repository.update(contribution.getId(), LocalDate.of(2026, 8, 6), "Vacation", new BigDecimal("150.00"));

        List<GoalContribution> contributions = repository.findAll();
        assertEquals(1, contributions.size());
        assertEquals("Vacation", contributions.get(0).getGoalName());
        assertEquals(new BigDecimal("150.00"), contributions.get(0).getAmount());
    }

    @Test
    void removeDeletesTheMatchingContribution(@TempDir Path tempDir) {
        GoalContributionRepository repository = new GoalContributionRepository(new DataPaths(tempDir));
        GoalContribution first = repository.add(LocalDate.of(2026, 8, 5), "Emergency fund", new BigDecimal("100.00"));
        repository.add(LocalDate.of(2026, 8, 6), "Vacation", new BigDecimal("50.00"));

        repository.remove(first.getId());

        List<GoalContribution> contributions = repository.findAll();
        assertEquals(1, contributions.size());
        assertEquals("Vacation", contributions.get(0).getGoalName());
    }

    @Test
    void loadsOlderLinesThatPredateTheIdColumn(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.goalContributionsFile(), String.join("\n",
                "# date|goalName|amount",
                "2026-08-14|Vacation|20.00",
                "2026-08-14|Celebration|50.00") + "\n");

        GoalContributionRepository repository = new GoalContributionRepository(dataPaths);
        List<GoalContribution> contributions = repository.findAll();

        assertEquals(2, contributions.size());
        assertEquals("Vacation", contributions.get(0).getGoalName());
        assertEquals("Celebration", contributions.get(1).getGoalName());
        assertEquals(1, contributions.get(0).getId());
        assertEquals(2, contributions.get(1).getId());

        // A newly added contribution must not collide with the ids just assigned above.
        GoalContribution added = repository.add(LocalDate.of(2026, 8, 15), "Vacation", new BigDecimal("10.00"));
        assertEquals(3, added.getId());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.YearMonth;

import static org.junit.jupiter.api.Assertions.assertEquals;

class MonthSummaryServiceTest {

    @Test
    void assemblesTotalsFromTheOtherServices(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        CategoryService categoryService = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        RecurringObligationService recurringObligationService = new RecurringObligationService(
                recurringObligationRepository, transactionRepository, categoryRepository, categoryService);
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);
        SavingsGoalService savingsGoalService = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository, categoryService);
        MonthSummaryService monthSummaryService = new MonthSummaryService(
                budgetService, savingsGoalService, recurringObligationService);

        YearMonth august = YearMonth.of(2026, 8);
        categoryRepository.add(new Category("Groceries", new BigDecimal("400.00")));
        categoryRepository.add(new Category("Subscriptions", new BigDecimal("20.00")));
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("3000.00"), "paycheck");
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("450.00"), "over target");
        recurringObligationRepository.add(new RecurringObligation("Streaming",
                new BigDecimal("120.00"), 12, LocalDate.of(2026, 8, 20), null, null));
        savingsGoalRepository.add(new SavingsGoal("Emergency fund", new BigDecimal("1000.00"), null));
        savingsGoalService.allocateLeftoverToGoal("Emergency fund", new BigDecimal("500.00"), august);

        MonthSummaryService.MonthSummary summary = monthSummaryService.summarize(august, LocalDate.of(2026, 8, 14));

        assertEquals(new BigDecimal("3000.00"), summary.getTotalIncome());
        assertEquals(new BigDecimal("450.00"), summary.getTotalExpenses());
        assertEquals(new BigDecimal("2550.00"), summary.getLeftover());
        assertEquals(new BigDecimal("2050.00"), summary.getAvailableLeftover());
        assertEquals(1, summary.getOverBudgetCount());
        assertEquals(1, summary.getGoalProgress().size());
        assertEquals(new BigDecimal("500.00"), summary.getGoalProgress().get(0).getSavedAmount());
        assertEquals(1, summary.getUpcomingPayments().size());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;

class RecurringObligationRepositoryTest {

    @Test
    void updateReplacesTheMatchingObligation(@TempDir Path tempDir) {
        RecurringObligationRepository repository = new RecurringObligationRepository(new DataPaths(tempDir));
        repository.add(new RecurringObligation("Streaming", new BigDecimal("120.00"),
                12, LocalDate.of(2026, 1, 15), null, null));

        repository.update("Streaming", new RecurringObligation("Streaming Plus",
                new BigDecimal("150.00"), 12, LocalDate.of(2026, 1, 15), null, "upgraded plan"));

        List<RecurringObligation> obligations = repository.findAll();
        assertEquals(1, obligations.size());
        assertEquals("Streaming Plus", obligations.get(0).getName());
        assertEquals(new BigDecimal("150.00"), obligations.get(0).getAmount());
        assertEquals("upgraded plan", obligations.get(0).getDescription().orElse(""));
    }

    @Test
    void removeDeletesTheMatchingObligation(@TempDir Path tempDir) {
        RecurringObligationRepository repository = new RecurringObligationRepository(new DataPaths(tempDir));
        repository.add(new RecurringObligation("Streaming", new BigDecimal("120.00"),
                12, LocalDate.of(2026, 1, 15), null, null));
        repository.add(new RecurringObligation("Gym", new BigDecimal("40.00"),
                1, LocalDate.of(2026, 1, 1), null, null));

        repository.remove("Streaming");

        List<RecurringObligation> obligations = repository.findAll();
        assertEquals(1, obligations.size());
        assertEquals("Gym", obligations.get(0).getName());
    }

    @Test
    void loadsOlderLinesThatStillHaveTheDroppedCategoryColumn(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.recurringObligationsFile(), String.join("\n",
                "# name|categoryName|amount|intervalMonths|startDate|endDate|description|amountPaid",
                "Streaming|Subscriptions|120.00|12|2026-01-15||Automatic renewal|50.00") + "\n");

        RecurringObligationRepository repository = new RecurringObligationRepository(dataPaths);
        List<RecurringObligation> obligations = repository.findAll();

        assertEquals(1, obligations.size());
        assertEquals("Streaming", obligations.get(0).getName());
        assertEquals(new BigDecimal("120.00"), obligations.get(0).getAmount());
        assertEquals(new BigDecimal("50.00"), obligations.get(0).getAmountPaid());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
