package com.example.finance;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class CategoryRepository {

    private final DataPaths dataPaths;
    private final List<Category> categories = new ArrayList<>();

    public CategoryRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<Category> findAll() {
        return Collections.unmodifiableList(categories);
    }

    public void add(Category category) {
        categories.add(category);
        persist();
    }

    public void update(String originalName, Category updated) {
        for (int i = 0; i < categories.size(); i++) {
            if (categories.get(i).getName().equals(originalName)) {
                categories.set(i, updated);
                break;
            }
        }
        persist();
    }

    public void remove(String name) {
        categories.removeIf(category -> category.getName().equals(name));
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.categoriesFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                String name = parts[0];
                BigDecimal monthlyTarget = new BigDecimal(parts[1]);
                categories.add(new Category(name, monthlyTarget));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed category line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|monthlyTarget");
        for (Category category : categories) {
            lines.add(category.getName() + "|" + category.getMonthlyTarget());
        }
        dataPaths.writeLinesAtomic(dataPaths.categoriesFile(), lines);
    }
}

package com.example.finance;

/**
 * Editing/deleting a category touches more than the category list: renaming
 * has to cascade into anything that references the old name by string, and
 * deleting has to be blocked while something still depends on it.
 */
public class CategoryService {

    private final CategoryRepository categoryRepository;
    private final TransactionRepository transactionRepository;
    private final RecurringObligationRepository recurringObligationRepository;
    private final SavingsGoalRepository savingsGoalRepository;

    public CategoryService(CategoryRepository categoryRepository, TransactionRepository transactionRepository,
                            RecurringObligationRepository recurringObligationRepository,
                            SavingsGoalRepository savingsGoalRepository) {
        this.categoryRepository = categoryRepository;
        this.transactionRepository = transactionRepository;
        this.recurringObligationRepository = recurringObligationRepository;
        this.savingsGoalRepository = savingsGoalRepository;
    }

    public void update(String originalName, Category updated) {
        categoryRepository.update(originalName, updated);
        if (!originalName.equals(updated.getName())) {
            transactionRepository.renameCategory(originalName, updated.getName());
        }
    }

    public void delete(String name) {
        boolean inUse = transactionRepository.findAll().stream().anyMatch(t -> t.getCategoryName().equals(name))
                || recurringObligationRepository.findAll().stream().anyMatch(o -> o.getName().equals(name))
                || savingsGoalRepository.findAll().stream().anyMatch(g -> g.getName().equals(name));
        if (inUse) {
            throw new IllegalStateException(
                    "Can't delete \"" + name + "\" — it still has transactions, obligations, or a savings goal.");
        }
        categoryRepository.remove(name);
    }
}

package com.example.finance;

import javafx.beans.property.ReadOnlyObjectProperty;
import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableRow;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.List;

/**
 * Category creation/edit/delete, plus category vs. target vs. actual for
 * the current month, with over-budget rows highlighted and a warning
 * summary above the table.
 */
public class CategorySummaryView {

    private final CategoryRepository categoryRepository;
    private final CategoryService categoryService;
    private final BudgetService budgetService;
    private final ReadOnlyObjectProperty<YearMonth> selectedMonth;

    private final ObservableList<BudgetService.CategoryTotal> rows = FXCollections.observableArrayList();
    private final Label warningLabel = new Label();

    public CategorySummaryView(CategoryRepository categoryRepository, CategoryService categoryService,
                                BudgetService budgetService, ReadOnlyObjectProperty<YearMonth> selectedMonth) {
        this.categoryRepository = categoryRepository;
        this.categoryService = categoryService;
        this.budgetService = budgetService;
        this.selectedMonth = selectedMonth;
        warningLabel.setWrapText(true);
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Categories", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(selectedMonth.get());
        rows.setAll(totals);
        long overBudgetCount = totals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();
        warningLabel.setText(overBudgetCount == 0
                ? "All categories are within target."
                : overBudgetCount + " categor" + (overBudgetCount == 1 ? "y is" : "ies are") + " over budget.");
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildCategoryManagement(), warningLabel);
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildCategoryManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Category name");
        TextField targetField = new TextField();
        targetField.setPromptText("Monthly target");
        Label status = new Label();
        status.setWrapText(true);

        TableView<BudgetService.CategoryTotal> table = buildTable();

        Button saveButton = new Button("Add category");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);
        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> refresh());

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                Category category = newSelection.getCategory();
                nameField.setText(category.getName());
                targetField.setText(category.getMonthlyTarget().toString());
                saveButton.setText("Update category");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add category");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            if (name.isEmpty()) {
                status.setText("Category name is required.");
                return;
            }
            try {
                BigDecimal monthlyTarget = new BigDecimal(targetField.getText().trim());
                BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    categoryRepository.add(new Category(name, monthlyTarget));
                    status.setText("Added category \"" + name + "\".");
                } else {
                    categoryService.update(selected.getCategory().getName(), new Category(name, monthlyTarget));
                    status.setText("Updated category \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Monthly target must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            try {
                categoryService.delete(selected.getCategory().getName());
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                status.setText("Deleted category \"" + selected.getCategory().getName() + "\".");
                refresh();
            } catch (IllegalStateException ex) {
                status.setText(ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Category:"), nameField, targetField, saveButton,
                deleteButton, refreshButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<BudgetService.CategoryTotal> buildTable() {
        TableView<BudgetService.CategoryTotal> table = new TableView<>(rows);

        TableColumn<BudgetService.CategoryTotal, String> nameCol = new TableColumn<>("Category");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getCategory().getName()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> targetCol = new TableColumn<>("Target");
        targetCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getCategory().getMonthlyTarget()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> actualCol = new TableColumn<>("Actual");
        actualCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getActual()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> remainingCol = new TableColumn<>("Remaining");
        remainingCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getRemaining()));

        table.getColumns().addAll(nameCol, targetCol, actualCol, remainingCol);

        table.setRowFactory(tv -> new TableRow<>() {
            @Override
            protected void updateItem(BudgetService.CategoryTotal item, boolean empty) {
                super.updateItem(item, empty);
                setStyle(!empty && item != null && item.isOverBudget() ? "-fx-background-color: #f8d7da;" : "");
            }
        });

        return table;
    }
}

package com.example.finance;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;

/**
 * Where finance data lives on disk, and the shared load/save plumbing every
 * repository uses. Defaults to a directory outside the project so it survives
 * across sessions regardless of where the project itself is checked out.
 */
public class DataPaths {

    private final Path dataDir;

    public DataPaths() {
        this(Path.of(System.getProperty("user.home"), ".personal-finance-app", "data"));
    }

    public DataPaths(Path dataDir) {
        this.dataDir = dataDir;
    }

    public Path categoriesFile() {
        return dataDir.resolve("categories.txt");
    }

    public Path transactionsFile() {
        return dataDir.resolve("transactions.txt");
    }

    public Path savingsGoalsFile() {
        return dataDir.resolve("savings_goals.txt");
    }

    public Path goalContributionsFile() {
        return dataDir.resolve("goal_contributions.txt");
    }

    public Path recurringObligationsFile() {
        return dataDir.resolve("recurring_obligations.txt");
    }

    public List<String> readLines(Path file) {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read " + file, e);
        }
    }

    public void writeLinesAtomic(Path file, List<String> lines) {
        try {
            Files.createDirectories(dataDir);
            Path tmp = file.resolveSibling(file.getFileName() + ".tmp");
            Files.write(tmp, lines);
            Files.move(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write " + file, e);
        }
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A leftover allocation toward a savings goal. Kept as its own append-only
 * log rather than mixed into the transaction ledger, so the expense ledger
 * stays a pure record of money in/out.
 */
public class GoalContribution {

    private final long id;
    private final LocalDate date;
    private final String goalName;
    private final BigDecimal amount;

    public GoalContribution(long id, LocalDate date, String goalName, BigDecimal amount) {
        this.id = id;
        this.date = date;
        this.goalName = goalName;
        this.amount = amount;
    }

    public long getId() {
        return id;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getGoalName() {
        return goalName;
    }

    public BigDecimal getAmount() {
        return amount;
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class GoalContributionRepository {

    private final DataPaths dataPaths;
    private final List<GoalContribution> contributions = new ArrayList<>();
    private long nextId = 1;

    public GoalContributionRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<GoalContribution> findAll() {
        return Collections.unmodifiableList(contributions);
    }

    public GoalContribution add(LocalDate date, String goalName, BigDecimal amount) {
        GoalContribution contribution = new GoalContribution(nextId++, date, goalName, amount);
        contributions.add(contribution);
        persist();
        return contribution;
    }

    public void update(long id, LocalDate date, String goalName, BigDecimal amount) {
        for (int i = 0; i < contributions.size(); i++) {
            if (contributions.get(i).getId() == id) {
                contributions.set(i, new GoalContribution(id, date, goalName, amount));
                break;
            }
        }
        persist();
    }

    public void remove(long id) {
        contributions.removeIf(contribution -> contribution.getId() == id);
        persist();
    }

    public void renameGoal(String oldName, String newName) {
        for (int i = 0; i < contributions.size(); i++) {
            GoalContribution contribution = contributions.get(i);
            if (contribution.getGoalName().equals(oldName)) {
                contributions.set(i, new GoalContribution(contribution.getId(), contribution.getDate(), newName,
                        contribution.getAmount()));
            }
        }
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.goalContributionsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                long id;
                LocalDate date;
                String goalName;
                BigDecimal amount;
                // The id column is a later addition; lines written before
                // that don't have one and get a freshly assigned id.
                if (parts.length >= 4) {
                    id = Long.parseLong(parts[0]);
                    date = LocalDate.parse(parts[1]);
                    goalName = parts[2];
                    amount = new BigDecimal(parts[3]);
                } else {
                    date = LocalDate.parse(parts[0]);
                    goalName = parts[1];
                    amount = new BigDecimal(parts[2]);
                    id = nextId;
                }
                contributions.add(new GoalContribution(id, date, goalName, amount));
                if (id >= nextId) {
                    nextId = id + 1;
                }
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed goal contribution line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# id|date|goalName|amount");
        for (GoalContribution contribution : contributions) {
            lines.add(contribution.getId() + "|" + contribution.getDate() + "|" + contribution.getGoalName() + "|"
                    + contribution.getAmount());
        }
        dataPaths.writeLinesAtomic(dataPaths.goalContributionsFile(), lines);
    }
}

package com.example.finance;

import javafx.application.Application;
import javafx.beans.property.ObjectProperty;
import javafx.beans.property.SimpleObjectProperty;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TabPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class MainApp extends Application {

    @Override
    public void start(Stage stage) {
        ObjectProperty<YearMonth> selectedMonth = new SimpleObjectProperty<>(YearMonth.now());

        DataPaths dataPaths = new DataPaths();
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        CategoryService categoryService = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        RecurringObligationService recurringObligationService = new RecurringObligationService(
                recurringObligationRepository, transactionRepository, categoryRepository, categoryService);
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);
        SavingsGoalService savingsGoalService = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository, categoryService);
        MonthSummaryService monthSummaryService = new MonthSummaryService(
                budgetService, savingsGoalService, recurringObligationService);

        MonthSummaryView monthSummaryView = new MonthSummaryView(monthSummaryService, selectedMonth);
        TransactionEntryView transactionEntryView = new TransactionEntryView(
                categoryRepository, transactionRepository, selectedMonth);
        CategorySummaryView categorySummaryView = new CategorySummaryView(
                categoryRepository, categoryService, budgetService, selectedMonth);
        SavingsGoalsView savingsGoalsView = new SavingsGoalsView(
                savingsGoalRepository, goalContributionRepository, savingsGoalService);
        RecurringObligationsView recurringObligationsView = new RecurringObligationsView(
                recurringObligationRepository, recurringObligationService);

        TabPane tabPane = new TabPane();
        tabPane.getTabs().addAll(
                monthSummaryView.asTab(),
                transactionEntryView.asTab(),
                categorySummaryView.asTab(),
                savingsGoalsView.asTab(),
                recurringObligationsView.asTab());

        // Entering any tab re-pulls the latest data, since transactions/goals/
        // obligations/categories entered in one tab feed the totals shown in the others.
        tabPane.getSelectionModel().selectedItemProperty().addListener((obs, oldTab, newTab) -> {
            transactionEntryView.refresh();
            categorySummaryView.refresh();
            savingsGoalsView.refresh();
            recurringObligationsView.refresh();
            monthSummaryView.refresh();
        });

        // Only the three month-scoped views need to react to month navigation;
        // Savings Goals and Recurring Obligations aren't month-scoped.
        selectedMonth.addListener((obs, oldMonth, newMonth) -> {
            monthSummaryView.refresh();
            transactionEntryView.refresh();
            categorySummaryView.refresh();
        });

        VBox mainLayout = new VBox(buildMonthNavigationBar(selectedMonth), tabPane);

        stage.setTitle("Personal Finance");
        stage.setScene(new Scene(mainLayout, 1024, 720));
        stage.show();
    }

    private HBox buildMonthNavigationBar(ObjectProperty<YearMonth> selectedMonth) {
        Label monthLabel = new Label();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MMMM yyyy", Locale.ROOT);
        monthLabel.setText(selectedMonth.get().format(formatter));
        selectedMonth.addListener((obs, oldMonth, newMonth) -> monthLabel.setText(newMonth.format(formatter)));

        Button previousButton = new Button("< Previous");
        previousButton.setOnAction(e -> selectedMonth.set(selectedMonth.get().minusMonths(1)));
        Button todayButton = new Button("Today");
        todayButton.setOnAction(e -> selectedMonth.set(YearMonth.now()));
        Button nextButton = new Button("Next >");
        nextButton.setOnAction(e -> selectedMonth.set(selectedMonth.get().plusMonths(1)));

        HBox navBar = new HBox(8, previousButton, monthLabel, nextButton, todayButton);
        navBar.setPadding(new Insets(12));
        navBar.setAlignment(Pos.CENTER_LEFT);
        return navBar;
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/**
 * Thin facade assembling BudgetService/SavingsGoalService/RecurringObligationService
 * output into one object for the month summary dashboard.
 */
public class MonthSummaryService {

    private final BudgetService budgetService;
    private final SavingsGoalService savingsGoalService;
    private final RecurringObligationService recurringObligationService;

    public MonthSummaryService(BudgetService budgetService, SavingsGoalService savingsGoalService,
                                RecurringObligationService recurringObligationService) {
        this.budgetService = budgetService;
        this.savingsGoalService = savingsGoalService;
        this.recurringObligationService = recurringObligationService;
    }

    public MonthSummary summarize(YearMonth month, LocalDate today) {
        List<BudgetService.CategoryTotal> categoryTotals = budgetService.categoryTotals(month);
        long overBudgetCount = categoryTotals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();

        return new MonthSummary(
                categoryTotals,
                budgetService.totalIncome(month),
                budgetService.totalExpenses(month),
                budgetService.leftover(month),
                savingsGoalService.availableLeftover(month),
                overBudgetCount,
                savingsGoalService.goalProgress(),
                recurringObligationService.upcomingPayments(today));
    }

    /**
     * Rolls up January through the given month, for that month's year.
     * Independent of savings goals/recurring obligations, since those
     * aren't month-scoped.
     */
    public YearToDateSummary summarizeYearToDate(YearMonth month) {
        YearMonth from = YearMonth.of(month.getYear(), 1);
        List<BudgetService.YtdCategoryTotal> categoryTotals = budgetService.categoryTotalsYearToDate(month);
        long overBudgetCount = categoryTotals.stream().filter(BudgetService.YtdCategoryTotal::isOverBudget).count();

        return new YearToDateSummary(
                month.getYear(),
                month,
                month.getMonthValue(),
                categoryTotals,
                budgetService.totalIncome(from, month),
                budgetService.totalExpenses(from, month),
                budgetService.leftover(from, month),
                overBudgetCount);
    }

    public static class MonthSummary {
        private final List<BudgetService.CategoryTotal> categoryTotals;
        private final BigDecimal totalIncome;
        private final BigDecimal totalExpenses;
        private final BigDecimal leftover;
        private final BigDecimal availableLeftover;
        private final long overBudgetCount;
        private final List<SavingsGoalService.GoalProgress> goalProgress;
        private final List<RecurringObligationService.UpcomingPayment> upcomingPayments;

        public MonthSummary(List<BudgetService.CategoryTotal> categoryTotals, BigDecimal totalIncome,
                             BigDecimal totalExpenses, BigDecimal leftover, BigDecimal availableLeftover,
                             long overBudgetCount, List<SavingsGoalService.GoalProgress> goalProgress,
                             List<RecurringObligationService.UpcomingPayment> upcomingPayments) {
            this.categoryTotals = categoryTotals;
            this.totalIncome = totalIncome;
            this.totalExpenses = totalExpenses;
            this.leftover = leftover;
            this.availableLeftover = availableLeftover;
            this.overBudgetCount = overBudgetCount;
            this.goalProgress = goalProgress;
            this.upcomingPayments = upcomingPayments;
        }

        public List<BudgetService.CategoryTotal> getCategoryTotals() {
            return categoryTotals;
        }

        public BigDecimal getTotalIncome() {
            return totalIncome;
        }

        public BigDecimal getTotalExpenses() {
            return totalExpenses;
        }

        public BigDecimal getLeftover() {
            return leftover;
        }

        public BigDecimal getAvailableLeftover() {
            return availableLeftover;
        }

        public long getOverBudgetCount() {
            return overBudgetCount;
        }

        public List<SavingsGoalService.GoalProgress> getGoalProgress() {
            return goalProgress;
        }

        public List<RecurringObligationService.UpcomingPayment> getUpcomingPayments() {
            return upcomingPayments;
        }
    }

    public static class YearToDateSummary {
        private final int year;
        private final YearMonth throughMonth;
        private final int monthsElapsed;
        private final List<BudgetService.YtdCategoryTotal> categoryTotals;
        private final BigDecimal totalIncome;
        private final BigDecimal totalExpenses;
        private final BigDecimal leftover;
        private final long overBudgetCount;

        public YearToDateSummary(int year, YearMonth throughMonth, int monthsElapsed,
                                  List<BudgetService.YtdCategoryTotal> categoryTotals, BigDecimal totalIncome,
                                  BigDecimal totalExpenses, BigDecimal leftover, long overBudgetCount) {
            this.year = year;
            this.throughMonth = throughMonth;
            this.monthsElapsed = monthsElapsed;
            this.categoryTotals = categoryTotals;
            this.totalIncome = totalIncome;
            this.totalExpenses = totalExpenses;
            this.leftover = leftover;
            this.overBudgetCount = overBudgetCount;
        }

        public int getYear() {
            return year;
        }

        public YearMonth getThroughMonth() {
            return throughMonth;
        }

        public int getMonthsElapsed() {
            return monthsElapsed;
        }

        public List<BudgetService.YtdCategoryTotal> getCategoryTotals() {
            return categoryTotals;
        }

        public BigDecimal getTotalIncome() {
            return totalIncome;
        }

        public BigDecimal getTotalExpenses() {
            return totalExpenses;
        }

        public BigDecimal getLeftover() {
            return leftover;
        }

        public long getOverBudgetCount() {
            return overBudgetCount;
        }
    }
}

package com.example.finance;

import javafx.beans.property.ReadOnlyObjectProperty;
import javafx.collections.FXCollections;
import javafx.geometry.Insets;
import javafx.scene.chart.BarChart;
import javafx.scene.chart.CategoryAxis;
import javafx.scene.chart.NumberAxis;
import javafx.scene.chart.PieChart;
import javafx.scene.chart.XYChart;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.Separator;
import javafx.scene.control.Tab;
import javafx.scene.layout.VBox;

import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/**
 * The "awareness budgeting" dashboard: leftover, warnings, goal and
 * upcoming-payment callouts, and the two headline charts, all for one month,
 * plus a year-to-date rollup section below it.
 */
public class MonthSummaryView {

    private final MonthSummaryService monthSummaryService;
    private final ReadOnlyObjectProperty<YearMonth> selectedMonth;

    private final VBox root = new VBox(12);
    private final Label leftoverLabel = new Label();
    private final Label warningLabel = new Label();
    private final Label goalsLabel = new Label();
    private final Label upcomingLabel = new Label();
    private final VBox chartsBox = new VBox(12);
    private final Label ytdHeaderLabel = new Label();
    private final Label ytdSummaryLabel = new Label();
    private final Label ytdWarningLabel = new Label();
    private final VBox ytdChartsBox = new VBox(12);

    public MonthSummaryView(MonthSummaryService monthSummaryService, ReadOnlyObjectProperty<YearMonth> selectedMonth) {
        this.monthSummaryService = monthSummaryService;
        this.selectedMonth = selectedMonth;
        buildLayout();
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Month Summary", root);
        tab.setClosable(false);
        return tab;
    }

    private void buildLayout() {
        for (Label label : List.of(leftoverLabel, warningLabel, goalsLabel, upcomingLabel,
                ytdHeaderLabel, ytdSummaryLabel, ytdWarningLabel)) {
            label.setWrapText(true);
        }
        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> refresh());
        root.setPadding(new Insets(12));
        root.getChildren().addAll(leftoverLabel, warningLabel, goalsLabel, upcomingLabel, chartsBox,
                new Separator(), ytdHeaderLabel, ytdSummaryLabel, ytdWarningLabel, ytdChartsBox, refreshButton);
    }

    public void refresh() {
        YearMonth month = selectedMonth.get();
        MonthSummaryService.MonthSummary summary = monthSummaryService.summarize(month, LocalDate.now());

        leftoverLabel.setText(String.format("Income %s − Expenses %s = Leftover %s (available to allocate: %s)",
                summary.getTotalIncome(), summary.getTotalExpenses(), summary.getLeftover(),
                summary.getAvailableLeftover()));

        warningLabel.setText(summary.getOverBudgetCount() == 0
                ? "All categories are within target."
                : summary.getOverBudgetCount() + " categor"
                        + (summary.getOverBudgetCount() == 1 ? "y is" : "ies are") + " over budget.");

        long goalsReached = summary.getGoalProgress().stream()
                .filter(g -> g.getSavedAmount().compareTo(g.getGoal().getTargetAmount()) >= 0)
                .count();
        goalsLabel.setText(summary.getGoalProgress().size() + " savings goal(s), " + goalsReached + " reached.");

        upcomingLabel.setText(summary.getUpcomingPayments().size() + " payment(s) due in the next 60 days.");

        chartsBox.getChildren().setAll(buildPieChart(summary), buildBarChart(summary));

        MonthSummaryService.YearToDateSummary ytd = monthSummaryService.summarizeYearToDate(month);

        ytdHeaderLabel.setText("Year to Date (Jan–" + month.getMonth() + " " + ytd.getYear() + ")");
        ytdSummaryLabel.setText(String.format("YTD Income %s − YTD Expenses %s = YTD Leftover %s",
                ytd.getTotalIncome(), ytd.getTotalExpenses(), ytd.getLeftover()));
        ytdWarningLabel.setText(ytd.getOverBudgetCount() == 0
                ? "All categories are within their YTD target."
                : ytd.getOverBudgetCount() + " categor"
                        + (ytd.getOverBudgetCount() == 1 ? "y is" : "ies are") + " over YTD target.");
        ytdChartsBox.getChildren().setAll(buildYtdBarChart(ytd));
    }

    private PieChart buildPieChart(MonthSummaryService.MonthSummary summary) {
        List<PieChart.Data> slices = summary.getCategoryTotals().stream()
                .filter(t -> !t.isIncomeOnly())
                .filter(t -> t.getActual().signum() > 0)
                .map(t -> new PieChart.Data(t.getCategory().getName(), t.getActual().doubleValue()))
                .toList();
        PieChart pieChart = new PieChart(FXCollections.observableArrayList(slices));
        pieChart.setTitle("Spending by category");
        return pieChart;
    }

    private BarChart<String, Number> buildBarChart(MonthSummaryService.MonthSummary summary) {
        BarChart<String, Number> barChart = new BarChart<>(new CategoryAxis(), new NumberAxis());
        barChart.setTitle("Target vs. actual by category");

        XYChart.Series<String, Number> targetSeries = new XYChart.Series<>();
        targetSeries.setName("Target");
        XYChart.Series<String, Number> actualSeries = new XYChart.Series<>();
        actualSeries.setName("Actual");

        // Income categories (e.g. a paycheck) are excluded — both charts
        // are about spending, and mixing income in would either dwarf real
        // spending slices or look like a wildly underspent category.
        for (BudgetService.CategoryTotal total : summary.getCategoryTotals()) {
            if (total.isIncomeOnly()) {
                continue;
            }
            String name = total.getCategory().getName();
            targetSeries.getData().add(new XYChart.Data<>(name, total.getCategory().getMonthlyTarget().doubleValue()));
            actualSeries.getData().add(new XYChart.Data<>(name, total.getActual().doubleValue()));
        }

        barChart.getData().addAll(targetSeries, actualSeries);
        return barChart;
    }

    private BarChart<String, Number> buildYtdBarChart(MonthSummaryService.YearToDateSummary ytd) {
        BarChart<String, Number> barChart = new BarChart<>(new CategoryAxis(), new NumberAxis());
        barChart.setTitle("YTD scaled target vs. actual by category");

        XYChart.Series<String, Number> targetSeries = new XYChart.Series<>();
        targetSeries.setName("Scaled Target");
        XYChart.Series<String, Number> actualSeries = new XYChart.Series<>();
        actualSeries.setName("YTD Actual");

        for (BudgetService.YtdCategoryTotal total : ytd.getCategoryTotals()) {
            if (total.isIncomeOnly()) {
                continue;
            }
            String name = total.getCategory().getName();
            targetSeries.getData().add(new XYChart.Data<>(name, total.getScaledTarget().doubleValue()));
            actualSeries.getData().add(new XYChart.Data<>(name, total.getActual().doubleValue()));
        }

        barChart.getData().addAll(targetSeries, actualSeries);
        return barChart;
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Optional;

public class RecurringObligation {

    private final String name;
    private final BigDecimal amount;
    private final int intervalMonths;
    private final LocalDate startDate;
    private final LocalDate endDate;
    private final String description;
    private final BigDecimal amountPaid;

    public RecurringObligation(String name, BigDecimal amount, int intervalMonths,
                                LocalDate startDate, LocalDate endDate, String description) {
        this(name, amount, intervalMonths, startDate, endDate, description, BigDecimal.ZERO);
    }

    /**
     * @param amountPaid optional starting balance for money already paid
     *                   toward this obligation before tracking began here;
     *                   defaults to zero. The running total shown to the
     *                   user is this plus whatever transactions get logged
     *                   against the obligation's own category going forward.
     */
    public RecurringObligation(String name, BigDecimal amount, int intervalMonths,
                                LocalDate startDate, LocalDate endDate, String description, BigDecimal amountPaid) {
        if (intervalMonths < 1 || intervalMonths > 600) {
            throw new IllegalArgumentException("intervalMonths must be between 1 and 600.");
        }
        this.name = name;
        this.amount = amount;
        this.intervalMonths = intervalMonths;
        this.startDate = startDate;
        this.endDate = endDate;
        this.description = description;
        this.amountPaid = amountPaid == null ? BigDecimal.ZERO : amountPaid;
    }

    public String getName() {
        return name;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public int getIntervalMonths() {
        return intervalMonths;
    }

    public LocalDate getStartDate() {
        return startDate;
    }

    public Optional<LocalDate> getEndDate() {
        return Optional.ofNullable(endDate);
    }

    public Optional<String> getDescription() {
        return Optional.ofNullable(description).filter(s -> !s.isBlank());
    }

    public BigDecimal getAmountPaid() {
        return amountPaid;
    }

    @Override
    public String toString() {
        return name;
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class RecurringObligationRepository {

    private final DataPaths dataPaths;
    private final List<RecurringObligation> obligations = new ArrayList<>();

    public RecurringObligationRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<RecurringObligation> findAll() {
        return Collections.unmodifiableList(obligations);
    }

    public void add(RecurringObligation obligation) {
        obligations.add(obligation);
        persist();
    }

    public void update(String originalName, RecurringObligation updated) {
        for (int i = 0; i < obligations.size(); i++) {
            if (obligations.get(i).getName().equals(originalName)) {
                obligations.set(i, updated);
                break;
            }
        }
        persist();
    }

    public void remove(String name) {
        obligations.removeIf(obligation -> obligation.getName().equals(name));
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.recurringObligationsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                // The categoryName column was dropped once obligations became
                // their own category; lines written before that still have
                // it in position 1, so they're shifted rather than lost.
                int offset = parts.length >= 8 ? 1 : 0;
                String name = parts[0];
                BigDecimal amount = new BigDecimal(parts[1 + offset]);
                int intervalMonths = Integer.parseInt(parts[2 + offset]);
                LocalDate startDate = LocalDate.parse(parts[3 + offset]);
                LocalDate endDate = parts[4 + offset].isEmpty() ? null : LocalDate.parse(parts[4 + offset]);
                String description = parts[5 + offset];
                int paidIndex = 6 + offset;
                BigDecimal amountPaid = parts.length > paidIndex && !parts[paidIndex].isEmpty()
                        ? new BigDecimal(parts[paidIndex]) : BigDecimal.ZERO;
                obligations.add(new RecurringObligation(name, amount, intervalMonths, startDate, endDate,
                        description, amountPaid));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed recurring obligation line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|amount|intervalMonths|startDate|endDate|description|amountPaid");
        for (RecurringObligation obligation : obligations) {
            lines.add(obligation.getName() + "|" + obligation.getAmount() + "|"
                    + obligation.getIntervalMonths() + "|" + obligation.getStartDate() + "|"
                    + obligation.getEndDate().map(LocalDate::toString).orElse("") + "|"
                    + obligation.getDescription().orElse("") + "|" + obligation.getAmountPaid());
        }
        dataPaths.writeLinesAtomic(dataPaths.recurringObligationsFile(), lines);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;

/**
 * Monthly-equivalent cost of spread expenses (annual subscriptions, etc.),
 * which obligations are due within a lookahead window, and how much has
 * been paid toward each one so far.
 */
public class RecurringObligationService {

    private static final int DEFAULT_LOOKAHEAD_DAYS = 60;

    private final RecurringObligationRepository recurringObligationRepository;
    private final TransactionRepository transactionRepository;
    private final CategoryRepository categoryRepository;
    private final CategoryService categoryService;

    public RecurringObligationService(RecurringObligationRepository recurringObligationRepository,
                                       TransactionRepository transactionRepository,
                                       CategoryRepository categoryRepository,
                                       CategoryService categoryService) {
        this.recurringObligationRepository = recurringObligationRepository;
        this.transactionRepository = transactionRepository;
        this.categoryRepository = categoryRepository;
        this.categoryService = categoryService;
    }

    /**
     * Adds the obligation, and — since it needs to be pickable as its own
     * category when logging a payment toward it — creates a matching
     * category if one with this name doesn't already exist, with its
     * target seeded from the obligation's monthly-equivalent cost.
     */
    public void addObligation(RecurringObligation obligation) {
        recurringObligationRepository.add(obligation);
        ensureCategoryExists(obligation.getName(), monthlyEquivalent(obligation));
    }

    /**
     * Updates an obligation, and — if the name changed — cascades the
     * rename to any transactions already logged against it and to its
     * matching category, if any. Also backfills a matching category if
     * this obligation predates that guarantee. An already-existing
     * category's target is left alone — only a newly created one is
     * seeded from the monthly-equivalent, so a target the user has since
     * customized isn't silently overwritten.
     */
    public void updateObligation(String originalName, RecurringObligation updated) {
        recurringObligationRepository.update(originalName, updated);
        if (!originalName.equals(updated.getName())) {
            transactionRepository.renameCategory(originalName, updated.getName());
            categoryRepository.findAll().stream()
                    .filter(c -> c.getName().equals(originalName))
                    .findFirst()
                    .ifPresent(existingCategory -> categoryService.update(
                            originalName, new Category(updated.getName(), existingCategory.getMonthlyTarget())));
        }
        ensureCategoryExists(updated.getName(), monthlyEquivalent(updated));
    }

    /**
     * The obligation's starting balance plus every expense transaction
     * logged against its own matching category — i.e. it goes up
     * automatically as payments are recorded, no manual bookkeeping needed
     * beyond the optional starting balance.
     */
    public BigDecimal totalPaid(RecurringObligation obligation) {
        BigDecimal fromTransactions = transactionRepository.findAll().stream()
                .filter(t -> t.getType() == TransactionType.EXPENSE)
                .filter(t -> t.getCategoryName().equals(obligation.getName()))
                .map(Transaction::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        return obligation.getAmountPaid().add(fromTransactions);
    }

    private void ensureCategoryExists(String name, BigDecimal monthlyTarget) {
        boolean categoryExists = categoryRepository.findAll().stream()
                .anyMatch(c -> c.getName().equals(name));
        if (!categoryExists) {
            categoryRepository.add(new Category(name, monthlyTarget));
        }
    }

    public BigDecimal monthlyEquivalent(RecurringObligation obligation) {
        return obligation.getAmount().divide(BigDecimal.valueOf(obligation.getIntervalMonths()), 2, RoundingMode.HALF_UP);
    }

    public List<UpcomingPayment> upcomingPayments(LocalDate today) {
        return upcomingPayments(today, DEFAULT_LOOKAHEAD_DAYS);
    }

    public List<UpcomingPayment> upcomingPayments(LocalDate today, int lookaheadDays) {
        LocalDate windowEnd = today.plusDays(lookaheadDays);
        List<UpcomingPayment> upcoming = new ArrayList<>();
        for (RecurringObligation obligation : recurringObligationRepository.findAll()) {
            LocalDate nextDue = nextOccurrenceOnOrAfter(obligation, today);
            if (nextDue != null && !nextDue.isAfter(windowEnd)) {
                upcoming.add(new UpcomingPayment(obligation, nextDue));
            }
        }
        upcoming.sort((a, b) -> a.getDueDate().compareTo(b.getDueDate()));
        return upcoming;
    }

    private LocalDate nextOccurrenceOnOrAfter(RecurringObligation obligation, LocalDate onOrAfter) {
        LocalDate occurrence = obligation.getStartDate();
        if (!occurrence.isBefore(onOrAfter)) {
            return withinEnd(obligation, occurrence) ? occurrence : null;
        }
        long monthsElapsed = ChronoUnit.MONTHS.between(occurrence, onOrAfter);
        long steps = monthsElapsed / obligation.getIntervalMonths();
        LocalDate candidate = occurrence.plusMonths(steps * obligation.getIntervalMonths());
        while (candidate.isBefore(onOrAfter)) {
            candidate = candidate.plusMonths(obligation.getIntervalMonths());
        }
        return withinEnd(obligation, candidate) ? candidate : null;
    }

    private boolean withinEnd(RecurringObligation obligation, LocalDate date) {
        return obligation.getEndDate().map(end -> !date.isAfter(end)).orElse(true);
    }

    public static class UpcomingPayment {
        private final RecurringObligation obligation;
        private final LocalDate dueDate;

        public UpcomingPayment(RecurringObligation obligation, LocalDate dueDate) {
            this.obligation = obligation;
            this.dueDate = dueDate;
        }

        public RecurringObligation getObligation() {
            return obligation;
        }

        public LocalDate getDueDate() {
            return dueDate;
        }
    }
}

package com.example.finance;

import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.DatePicker;
import javafx.scene.control.Label;
import javafx.scene.control.Separator;
import javafx.scene.control.Spinner;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * Long-term/spread expenses (annual subscriptions, contracts): entry/edit/
 * delete, the full obligations table, and what's due within the lookahead
 * window. Each obligation is its own category (managed on the Categories
 * tab), so there's no separate category picker here.
 */
public class RecurringObligationsView {

    private final RecurringObligationRepository recurringObligationRepository;
    private final RecurringObligationService recurringObligationService;

    private final ObservableList<RecurringObligation> obligationRows = FXCollections.observableArrayList();
    private final ObservableList<RecurringObligationService.UpcomingPayment> upcomingRows = FXCollections.observableArrayList();

    public RecurringObligationsView(RecurringObligationRepository recurringObligationRepository,
                                     RecurringObligationService recurringObligationService) {
        this.recurringObligationRepository = recurringObligationRepository;
        this.recurringObligationService = recurringObligationService;
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Obligations", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        obligationRows.setAll(recurringObligationRepository.findAll());
        upcomingRows.setAll(recurringObligationService.upcomingPayments(LocalDate.now()));
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildObligationManagement(), new Separator(),
                new Label("Upcoming payments (next 60 days)"), buildUpcomingTable());
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildObligationManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Name");
        TextField amountField = new TextField();
        amountField.setPromptText("Amount");
        Spinner<Integer> intervalSpinner = new Spinner<>(1, 600, 12);
        intervalSpinner.setEditable(true);
        intervalSpinner.setPrefWidth(90);
        DatePicker startDatePicker = new DatePicker(LocalDate.now());
        DatePicker endDatePicker = new DatePicker();
        endDatePicker.setPromptText("End date (optional)");
        TextField descriptionField = new TextField();
        descriptionField.setPromptText("Notes (optional)");
        TextField amountPaidField = new TextField();
        amountPaidField.setPromptText("Paid so far (optional)");
        Label status = new Label();
        status.setWrapText(true);

        TableView<RecurringObligation> table = buildObligationTable();

        Button saveButton = new Button("Add obligation");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                nameField.setText(newSelection.getName());
                amountField.setText(newSelection.getAmount().toString());
                intervalSpinner.getValueFactory().setValue(newSelection.getIntervalMonths());
                startDatePicker.setValue(newSelection.getStartDate());
                endDatePicker.setValue(newSelection.getEndDate().orElse(null));
                descriptionField.setText(newSelection.getDescription().orElse(""));
                amountPaidField.setText(newSelection.getAmountPaid().toString());
                saveButton.setText("Update obligation");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add obligation");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            LocalDate startDate = startDatePicker.getValue();
            if (name.isEmpty() || startDate == null) {
                status.setText("Name and start date are required.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                String paidText = amountPaidField.getText().trim();
                BigDecimal amountPaid = paidText.isEmpty() ? BigDecimal.ZERO : new BigDecimal(paidText);
                RecurringObligation updated = new RecurringObligation(name, amount,
                        intervalSpinner.getValue(), startDate, endDatePicker.getValue(),
                        descriptionField.getText().trim(), amountPaid);
                RecurringObligation selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    recurringObligationService.addObligation(updated);
                    status.setText("Added obligation \"" + name + "\" (and a matching category).");
                } else {
                    recurringObligationService.updateObligation(selected.getName(), updated);
                    status.setText("Updated obligation \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                amountField.clear();
                descriptionField.clear();
                amountPaidField.clear();
                endDatePicker.setValue(null);
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Amount and paid-so-far must be numbers.");
            } catch (IllegalArgumentException ex) {
                status.setText(ex.getMessage());
            }
        });

        deleteButton.setOnAction(e -> {
            RecurringObligation selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            recurringObligationRepository.remove(selected.getName());
            table.getSelectionModel().clearSelection();
            nameField.clear();
            amountField.clear();
            descriptionField.clear();
            amountPaidField.clear();
            endDatePicker.setValue(null);
            status.setText("Deleted obligation \"" + selected.getName() + "\".");
            refresh();
        });

        FlowPane form = new FlowPane(8, 8, new Label("Obligation:"), nameField, amountField,
                intervalSpinner, startDatePicker, endDatePicker, descriptionField, amountPaidField,
                saveButton, deleteButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<RecurringObligation> buildObligationTable() {
        TableView<RecurringObligation> table = new TableView<>(obligationRows);

        TableColumn<RecurringObligation, String> nameCol = new TableColumn<>("Name");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getName()));

        TableColumn<RecurringObligation, BigDecimal> amountCol = new TableColumn<>("Amount");
        amountCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getAmount()));

        TableColumn<RecurringObligation, Integer> intervalCol = new TableColumn<>("Every (months)");
        intervalCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getIntervalMonths()));

        TableColumn<RecurringObligation, BigDecimal> monthlyCol = new TableColumn<>("Monthly equiv.");
        monthlyCol.setCellValueFactory(cell ->
                new SimpleObjectProperty<>(recurringObligationService.monthlyEquivalent(cell.getValue())));

        TableColumn<RecurringObligation, LocalDate> startCol = new TableColumn<>("Start");
        startCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getStartDate()));

        TableColumn<RecurringObligation, String> endCol = new TableColumn<>("End");
        endCol.setCellValueFactory(cell -> new SimpleStringProperty(
                cell.getValue().getEndDate().map(LocalDate::toString).orElse("")));

        TableColumn<RecurringObligation, String> notesCol = new TableColumn<>("Notes");
        notesCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getDescription().orElse("")));

        TableColumn<RecurringObligation, BigDecimal> paidCol = new TableColumn<>("Paid to date");
        paidCol.setCellValueFactory(cell ->
                new SimpleObjectProperty<>(recurringObligationService.totalPaid(cell.getValue())));

        table.getColumns().addAll(nameCol, amountCol, intervalCol, monthlyCol, startCol, endCol, paidCol, notesCol);
        return table;
    }

    private TableView<RecurringObligationService.UpcomingPayment> buildUpcomingTable() {
        TableView<RecurringObligationService.UpcomingPayment> table = new TableView<>(upcomingRows);

        TableColumn<RecurringObligationService.UpcomingPayment, String> nameCol = new TableColumn<>("Obligation");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getObligation().getName()));

        TableColumn<RecurringObligationService.UpcomingPayment, LocalDate> dueCol = new TableColumn<>("Due");
        dueCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getDueDate()));

        TableColumn<RecurringObligationService.UpcomingPayment, BigDecimal> amountCol = new TableColumn<>("Amount");
        amountCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getObligation().getAmount()));

        table.getColumns().addAll(nameCol, dueCol, amountCol);
        return table;
    }
}

