package com.example.finance;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class CategoryRepository {

    private final DataPaths dataPaths;
    private final List<Category> categories = new ArrayList<>();

    public CategoryRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<Category> findAll() {
        return Collections.unmodifiableList(categories);
    }

    public void add(Category category) {
        categories.add(category);
        persist();
    }

    public void update(String originalName, Category updated) {
        for (int i = 0; i < categories.size(); i++) {
            if (categories.get(i).getName().equals(originalName)) {
                categories.set(i, updated);
                break;
            }
        }
        persist();
    }

    public void remove(String name) {
        categories.removeIf(category -> category.getName().equals(name));
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.categoriesFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                String name = parts[0];
                BigDecimal monthlyTarget = new BigDecimal(parts[1]);
                categories.add(new Category(name, monthlyTarget));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed category line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|monthlyTarget");
        for (Category category : categories) {
            lines.add(category.getName() + "|" + category.getMonthlyTarget());
        }
        dataPaths.writeLinesAtomic(dataPaths.categoriesFile(), lines);
    }
}

package com.example.finance;

/**
 * Editing/deleting a category touches more than the category list: renaming
 * has to cascade into anything that references the old name by string, and
 * deleting has to be blocked while something still depends on it.
 */
public class CategoryService {

    private final CategoryRepository categoryRepository;
    private final TransactionRepository transactionRepository;
    private final RecurringObligationRepository recurringObligationRepository;
    private final SavingsGoalRepository savingsGoalRepository;

    public CategoryService(CategoryRepository categoryRepository, TransactionRepository transactionRepository,
                            RecurringObligationRepository recurringObligationRepository,
                            SavingsGoalRepository savingsGoalRepository) {
        this.categoryRepository = categoryRepository;
        this.transactionRepository = transactionRepository;
        this.recurringObligationRepository = recurringObligationRepository;
        this.savingsGoalRepository = savingsGoalRepository;
    }

    public void update(String originalName, Category updated) {
        categoryRepository.update(originalName, updated);
        if (!originalName.equals(updated.getName())) {
            transactionRepository.renameCategory(originalName, updated.getName());
        }
    }

    public void delete(String name) {
        boolean inUse = transactionRepository.findAll().stream().anyMatch(t -> t.getCategoryName().equals(name))
                || recurringObligationRepository.findAll().stream().anyMatch(o -> o.getName().equals(name))
                || savingsGoalRepository.findAll().stream().anyMatch(g -> g.getName().equals(name));
        if (inUse) {
            throw new IllegalStateException(
                    "Can't delete \"" + name + "\" — it still has transactions, obligations, or a savings goal.");
        }
        categoryRepository.remove(name);
    }
}

package com.example.finance;

import javafx.beans.property.ReadOnlyObjectProperty;
import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableRow;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.YearMonth;
import java.util.List;

/**
 * Category creation/edit/delete, plus category vs. target vs. actual for
 * the current month, with over-budget rows highlighted and a warning
 * summary above the table.
 */
public class CategorySummaryView {

    private final CategoryRepository categoryRepository;
    private final CategoryService categoryService;
    private final BudgetService budgetService;
    private final ReadOnlyObjectProperty<YearMonth> selectedMonth;

    private final ObservableList<BudgetService.CategoryTotal> rows = FXCollections.observableArrayList();
    private final Label warningLabel = new Label();

    public CategorySummaryView(CategoryRepository categoryRepository, CategoryService categoryService,
                                BudgetService budgetService, ReadOnlyObjectProperty<YearMonth> selectedMonth) {
        this.categoryRepository = categoryRepository;
        this.categoryService = categoryService;
        this.budgetService = budgetService;
        this.selectedMonth = selectedMonth;
        warningLabel.setWrapText(true);
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Categories", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(selectedMonth.get());
        rows.setAll(totals);
        long overBudgetCount = totals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();
        warningLabel.setText(overBudgetCount == 0
                ? "All categories are within target."
                : overBudgetCount + " categor" + (overBudgetCount == 1 ? "y is" : "ies are") + " over budget.");
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildCategoryManagement(), warningLabel);
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildCategoryManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Category name");
        TextField targetField = new TextField();
        targetField.setPromptText("Monthly target");
        Label status = new Label();
        status.setWrapText(true);

        TableView<BudgetService.CategoryTotal> table = buildTable();

        Button saveButton = new Button("Add category");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);
        Button refreshButton = new Button("Refresh");
        refreshButton.setOnAction(e -> refresh());

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                Category category = newSelection.getCategory();
                nameField.setText(category.getName());
                targetField.setText(category.getMonthlyTarget().toString());
                saveButton.setText("Update category");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add category");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            if (name.isEmpty()) {
                status.setText("Category name is required.");
                return;
            }
            try {
                BigDecimal monthlyTarget = new BigDecimal(targetField.getText().trim());
                BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    categoryRepository.add(new Category(name, monthlyTarget));
                    status.setText("Added category \"" + name + "\".");
                } else {
                    categoryService.update(selected.getCategory().getName(), new Category(name, monthlyTarget));
                    status.setText("Updated category \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Monthly target must be a number.");
            }
        });

        deleteButton.setOnAction(e -> {
            BudgetService.CategoryTotal selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            try {
                categoryService.delete(selected.getCategory().getName());
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                status.setText("Deleted category \"" + selected.getCategory().getName() + "\".");
                refresh();
            } catch (IllegalStateException ex) {
                status.setText(ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Category:"), nameField, targetField, saveButton,
                deleteButton, refreshButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<BudgetService.CategoryTotal> buildTable() {
        TableView<BudgetService.CategoryTotal> table = new TableView<>(rows);

        TableColumn<BudgetService.CategoryTotal, String> nameCol = new TableColumn<>("Category");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getCategory().getName()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> targetCol = new TableColumn<>("Target");
        targetCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getCategory().getMonthlyTarget()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> actualCol = new TableColumn<>("Actual");
        actualCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getActual()));

        TableColumn<BudgetService.CategoryTotal, BigDecimal> remainingCol = new TableColumn<>("Remaining");
        remainingCol.setCellValueFactory(cell -> new SimpleObjectProperty<>(cell.getValue().getRemaining()));

        table.getColumns().addAll(nameCol, targetCol, actualCol, remainingCol);

        table.setRowFactory(tv -> new TableRow<>() {
            @Override
            protected void updateItem(BudgetService.CategoryTotal item, boolean empty) {
                super.updateItem(item, empty);
                setStyle(!empty && item != null && item.isOverBudget() ? "-fx-background-color: #f8d7da;" : "");
            }
        });

        return table;
    }
}

package com.example.finance;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.List;

/**
 * Where finance data lives on disk, and the shared load/save plumbing every
 * repository uses. Defaults to a directory outside the project so it survives
 * across sessions regardless of where the project itself is checked out.
 */
public class DataPaths {

    private final Path dataDir;

    public DataPaths() {
        this(Path.of(System.getProperty("user.home"), ".personal-finance-app", "data"));
    }

    public DataPaths(Path dataDir) {
        this.dataDir = dataDir;
    }

    public Path categoriesFile() {
        return dataDir.resolve("categories.txt");
    }

    public Path transactionsFile() {
        return dataDir.resolve("transactions.txt");
    }

    public Path savingsGoalsFile() {
        return dataDir.resolve("savings_goals.txt");
    }

    public Path goalContributionsFile() {
        return dataDir.resolve("goal_contributions.txt");
    }

    public Path recurringObligationsFile() {
        return dataDir.resolve("recurring_obligations.txt");
    }

    public List<String> readLines(Path file) {
        try {
            if (!Files.exists(file)) {
                return List.of();
            }
            return Files.readAllLines(file);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to read " + file, e);
        }
    }

    public void writeLinesAtomic(Path file, List<String> lines) {
        try {
            Files.createDirectories(dataDir);
            Path tmp = file.resolveSibling(file.getFileName() + ".tmp");
            Files.write(tmp, lines);
            Files.move(tmp, file, StandardCopyOption.ATOMIC_MOVE, StandardCopyOption.REPLACE_EXISTING);
        } catch (IOException e) {
            throw new UncheckedIOException("Failed to write " + file, e);
        }
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;

/**
 * A leftover allocation toward a savings goal. Kept as its own append-only
 * log rather than mixed into the transaction ledger, so the expense ledger
 * stays a pure record of money in/out.
 */
public class GoalContribution {

    private final long id;
    private final LocalDate date;
    private final String goalName;
    private final BigDecimal amount;

    public GoalContribution(long id, LocalDate date, String goalName, BigDecimal amount) {
        this.id = id;
        this.date = date;
        this.goalName = goalName;
        this.amount = amount;
    }

    public long getId() {
        return id;
    }

    public LocalDate getDate() {
        return date;
    }

    public String getGoalName() {
        return goalName;
    }

    public BigDecimal getAmount() {
        return amount;
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class GoalContributionRepository {

    private final DataPaths dataPaths;
    private final List<GoalContribution> contributions = new ArrayList<>();
    private long nextId = 1;

    public GoalContributionRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<GoalContribution> findAll() {
        return Collections.unmodifiableList(contributions);
    }

    public GoalContribution add(LocalDate date, String goalName, BigDecimal amount) {
        GoalContribution contribution = new GoalContribution(nextId++, date, goalName, amount);
        contributions.add(contribution);
        persist();
        return contribution;
    }

    public void update(long id, LocalDate date, String goalName, BigDecimal amount) {
        for (int i = 0; i < contributions.size(); i++) {
            if (contributions.get(i).getId() == id) {
                contributions.set(i, new GoalContribution(id, date, goalName, amount));
                break;
            }
        }
        persist();
    }

    public void remove(long id) {
        contributions.removeIf(contribution -> contribution.getId() == id);
        persist();
    }

    public void renameGoal(String oldName, String newName) {
        for (int i = 0; i < contributions.size(); i++) {
            GoalContribution contribution = contributions.get(i);
            if (contribution.getGoalName().equals(oldName)) {
                contributions.set(i, new GoalContribution(contribution.getId(), contribution.getDate(), newName,
                        contribution.getAmount()));
            }
        }
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.goalContributionsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                long id;
                LocalDate date;
                String goalName;
                BigDecimal amount;
                // The id column is a later addition; lines written before
                // that don't have one and get a freshly assigned id.
                if (parts.length >= 4) {
                    id = Long.parseLong(parts[0]);
                    date = LocalDate.parse(parts[1]);
                    goalName = parts[2];
                    amount = new BigDecimal(parts[3]);
                } else {
                    date = LocalDate.parse(parts[0]);
                    goalName = parts[1];
                    amount = new BigDecimal(parts[2]);
                    id = nextId;
                }
                contributions.add(new GoalContribution(id, date, goalName, amount));
                if (id >= nextId) {
                    nextId = id + 1;
                }
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed goal contribution line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# id|date|goalName|amount");
        for (GoalContribution contribution : contributions) {
            lines.add(contribution.getId() + "|" + contribution.getDate() + "|" + contribution.getGoalName() + "|"
                    + contribution.getAmount());
        }
        dataPaths.writeLinesAtomic(dataPaths.goalContributionsFile(), lines);
    }
}

package com.example.finance;

import javafx.application.Application;
import javafx.beans.property.ObjectProperty;
import javafx.beans.property.SimpleObjectProperty;
import javafx.geometry.Insets;
import javafx.geometry.Pos;
import javafx.scene.Scene;
import javafx.scene.control.Button;
import javafx.scene.control.Label;
import javafx.scene.control.TabPane;
import javafx.scene.layout.HBox;
import javafx.scene.layout.VBox;
import javafx.stage.Stage;

import java.time.YearMonth;
import java.time.format.DateTimeFormatter;
import java.util.Locale;

public class MainApp extends Application {

    @Override
    public void start(Stage stage) {
        ObjectProperty<YearMonth> selectedMonth = new SimpleObjectProperty<>(YearMonth.now());

        DataPaths dataPaths = new DataPaths();
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        CategoryService categoryService = new CategoryService(
                categoryRepository, transactionRepository, recurringObligationRepository, savingsGoalRepository);
        RecurringObligationService recurringObligationService = new RecurringObligationService(
                recurringObligationRepository, transactionRepository, categoryRepository, categoryService);
        BudgetService budgetService = new BudgetService(categoryRepository, transactionRepository);
        SavingsGoalService savingsGoalService = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository, categoryService);
        MonthSummaryService monthSummaryService = new MonthSummaryService(
                budgetService, savingsGoalService, recurringObligationService);

        MonthSummaryView monthSummaryView = new MonthSummaryView(monthSummaryService, selectedMonth);
        TransactionEntryView transactionEntryView = new TransactionEntryView(
                categoryRepository, transactionRepository, selectedMonth);
        CategorySummaryView categorySummaryView = new CategorySummaryView(
                categoryRepository, categoryService, budgetService, selectedMonth);
        SavingsGoalsView savingsGoalsView = new SavingsGoalsView(
                savingsGoalRepository, goalContributionRepository, savingsGoalService);
        RecurringObligationsView recurringObligationsView = new RecurringObligationsView(
                recurringObligationRepository, recurringObligationService);

        TabPane tabPane = new TabPane();
        tabPane.getTabs().addAll(
                monthSummaryView.asTab(),
                transactionEntryView.asTab(),
                categorySummaryView.asTab(),
                savingsGoalsView.asTab(),
                recurringObligationsView.asTab());

        // Entering any tab re-pulls the latest data, since transactions/goals/
        // obligations/categories entered in one tab feed the totals shown in the others.
        tabPane.getSelectionModel().selectedItemProperty().addListener((obs, oldTab, newTab) -> {
            transactionEntryView.refresh();
            categorySummaryView.refresh();
            savingsGoalsView.refresh();
            recurringObligationsView.refresh();
            monthSummaryView.refresh();
        });

        // Only the three month-scoped views need to react to month navigation;
        // Savings Goals and Recurring Obligations aren't month-scoped.
        selectedMonth.addListener((obs, oldMonth, newMonth) -> {
            monthSummaryView.refresh();
            transactionEntryView.refresh();
            categorySummaryView.refresh();
        });

        VBox mainLayout = new VBox(buildMonthNavigationBar(selectedMonth), tabPane);

        stage.setTitle("Personal Finance");
        stage.setScene(new Scene(mainLayout, 1024, 720));
        stage.show();
    }

    private HBox buildMonthNavigationBar(ObjectProperty<YearMonth> selectedMonth) {
        Label monthLabel = new Label();
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MMMM yyyy", Locale.ROOT);
        monthLabel.setText(selectedMonth.get().format(formatter));
        selectedMonth.addListener((obs, oldMonth, newMonth) -> monthLabel.setText(newMonth.format(formatter)));

        Button previousButton = new Button("< Previous");
        previousButton.setOnAction(e -> selectedMonth.set(selectedMonth.get().minusMonths(1)));
        Button todayButton = new Button("Today");
        todayButton.setOnAction(e -> selectedMonth.set(YearMonth.now()));
        Button nextButton = new Button("Next >");
        nextButton.setOnAction(e -> selectedMonth.set(selectedMonth.get().plusMonths(1)));

        HBox navBar = new HBox(8, previousButton, monthLabel, nextButton, todayButton);
        navBar.setPadding(new Insets(12));
        navBar.setAlignment(Pos.CENTER_LEFT);
        return navBar;
    }

    public static void main(String[] args) {
        launch(args);
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

/**
 * Thin facade assembling BudgetService/SavingsGoalService/RecurringObligationService
 * output into one object for the month summary dashboard.
 */
public class MonthSummaryService {

    private final BudgetService budgetService;
    private final SavingsGoalService savingsGoalService;
    private final RecurringObligationService recurringObligationService;

    public MonthSummaryService(BudgetService budgetService, SavingsGoalService savingsGoalService,
                                RecurringObligationService recurringObligationService) {
        this.budgetService = budgetService;
        this.savingsGoalService = savingsGoalService;
        this.recurringObligationService = recurringObligationService;
    }

    public MonthSummary summarize(YearMonth month, LocalDate today) {
        List<BudgetService.CategoryTotal> categoryTotals = budgetService.categoryTotals(month);
        long overBudgetCount = categoryTotals.stream().filter(BudgetService.CategoryTotal::isOverBudget).count();

        return new MonthSummary(
                categoryTotals,
                budgetService.totalIncome(month),
                budgetService.totalExpenses(month),
                budgetService.leftover(month),
                savingsGoalService.availableLeftover(month),
                overBudgetCount,
                savingsGoalService.goalProgress(),
                recurringObligationService.upcomingPayments(today));
    }

    /**
     * Rolls up January through the given month, for that month's year.
     * Independent of savings goals/recurring obligations, since those
     * aren't month-scoped.
     */
    public YearToDateSummary summarizeYearToDate(YearMonth month) {
        YearMonth from = YearMonth.of(month.getYear(), 1);
        List<BudgetService.YtdCategoryTotal> categoryTotals = budgetService.categoryTotalsYearToDate(month);
        long overBudgetCount = categoryTotals.stream().filter(BudgetService.YtdCategoryTotal::isOverBudget).count();

        return new YearToDateSummary(
                month.getYear(),
                month,
                month.getMonthValue(),
                categoryTotals,
                budgetService.totalIncome(from, month),
                budgetService.totalExpenses(from, month),
                budgetService.leftover(from, month),
                overBudgetCount);
    }

    public static class MonthSummary {
        private final List<BudgetService.CategoryTotal> categoryTotals;
        private final BigDecimal totalIncome;
        private final BigDecimal totalExpenses;
        private final BigDecimal leftover;
        private final BigDecimal availableLeftover;
