        return name;
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class SavingsGoalRepository {

    private final DataPaths dataPaths;
    private final List<SavingsGoal> goals = new ArrayList<>();

    public SavingsGoalRepository(DataPaths dataPaths) {
        this.dataPaths = dataPaths;
        load();
    }

    public List<SavingsGoal> findAll() {
        return Collections.unmodifiableList(goals);
    }

    public void add(SavingsGoal goal) {
        goals.add(goal);
        persist();
    }

    public void update(String originalName, SavingsGoal updated) {
        for (int i = 0; i < goals.size(); i++) {
            if (goals.get(i).getName().equals(originalName)) {
                goals.set(i, updated);
                break;
            }
        }
        persist();
    }

    public void remove(String name) {
        goals.removeIf(goal -> goal.getName().equals(name));
        persist();
    }

    private void load() {
        for (String line : dataPaths.readLines(dataPaths.savingsGoalsFile())) {
            if (line.isBlank() || line.startsWith("#")) {
                continue;
            }
            try {
                String[] parts = line.split("\\|", -1);
                String name = parts[0];
                BigDecimal targetAmount = new BigDecimal(parts[1]);
                LocalDate targetDate = parts[2].isEmpty() ? null : LocalDate.parse(parts[2]);
                // Lines written before goals pointed at an existing category
                // lack this column; default to the goal's own name, which
                // matches the pseudo-category that used to be auto-created.
                String categoryName = (parts.length >= 4 && !parts[3].isEmpty()) ? parts[3] : name;
                goals.add(new SavingsGoal(name, targetAmount, targetDate, categoryName));
            } catch (RuntimeException e) {
                System.err.println("Skipping malformed savings goal line: " + line + " (" + e.getMessage() + ")");
            }
        }
    }

    private void persist() {
        List<String> lines = new ArrayList<>();
        lines.add("# name|targetAmount|targetDate|categoryName");
        for (SavingsGoal goal : goals) {
            lines.add(goal.getName() + "|" + goal.getTargetAmount() + "|"
                    + goal.getTargetDate().map(LocalDate::toString).orElse("") + "|" + goal.getCategoryName());
        }
        dataPaths.writeLinesAtomic(dataPaths.savingsGoalsFile(), lines);
    }

    public void renameCategory(String oldName, String newName) {
        for (int i = 0; i < goals.size(); i++) {
            SavingsGoal goal = goals.get(i);
            if (goal.getCategoryName().equals(oldName)) {
                goals.set(i, new SavingsGoal(goal.getName(), goal.getTargetAmount(),
                        goal.getTargetDate().orElse(null), newName));
            }
        }
        persist();
    }
}

package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/**
 * Goal progress, and allocating a month's leftover to a goal. Allocations
 * are gated against "leftover minus what's already been allocated this
 * month" so the same leftover can't be assigned twice.
 */
public class SavingsGoalService {

    private final SavingsGoalRepository savingsGoalRepository;
    private final GoalContributionRepository goalContributionRepository;
    private final BudgetService budgetService;
    private final CategoryRepository categoryRepository;

    public SavingsGoalService(SavingsGoalRepository savingsGoalRepository,
                               GoalContributionRepository goalContributionRepository,
                               BudgetService budgetService,
                               CategoryRepository categoryRepository) {
        this.savingsGoalRepository = savingsGoalRepository;
        this.goalContributionRepository = goalContributionRepository;
        this.budgetService = budgetService;
        this.categoryRepository = categoryRepository;
    }

    public void addGoal(SavingsGoal goal) {
        validateCategoryExists(goal.getCategoryName());
        savingsGoalRepository.add(goal);
    }

    /**
     * Updates a goal's target amount/date/assigned category, and — if the
     * name changed — cascades the rename to its contribution history so
     * past progress isn't silently orphaned.
     */
    public void updateGoal(String originalName, SavingsGoal updated) {
        validateCategoryExists(updated.getCategoryName());
        savingsGoalRepository.update(originalName, updated);
        if (!originalName.equals(updated.getName())) {
            goalContributionRepository.renameGoal(originalName, updated.getName());
        }
    }

    private void validateCategoryExists(String categoryName) {
        boolean exists = categoryRepository.findAll().stream().anyMatch(c -> c.getName().equals(categoryName));
        if (!exists) {
            throw new IllegalArgumentException("No such category: \"" + categoryName + "\".");
        }
    }

    /**
     * Refuses to delete a goal that already has money saved toward it,
     * since that history would otherwise vanish silently.
     */
    public void deleteGoal(String name) {
        BigDecimal saved = totalSaved(name);
        if (saved.signum() > 0) {
            throw new IllegalStateException(
                    "Can't delete \"" + name + "\" — it already has " + saved + " saved. Rename it instead.");
        }
        savingsGoalRepository.remove(name);
    }

    public List<GoalProgress> goalProgress() {
        List<GoalProgress> progress = new ArrayList<>();
        for (SavingsGoal goal : savingsGoalRepository.findAll()) {
            progress.add(new GoalProgress(goal, totalSaved(goal.getName())));
        }
        return progress;
    }

    public BigDecimal totalSaved(String goalName) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> c.getGoalName().equals(goalName))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal totalContributions(YearMonth month) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> YearMonth.from(c.getDate()).equals(month))
                .map(GoalContribution::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }

    public BigDecimal availableLeftover(YearMonth month) {
        return budgetService.leftover(month).subtract(totalContributions(month));
    }

    public void allocateLeftoverToGoal(String goalName, BigDecimal amount, YearMonth month) {
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Allocation amount must be positive.");
        }
        if (amount.compareTo(availableLeftover(month)) > 0) {
            throw new IllegalArgumentException("Allocation exceeds available leftover.");
        }
        goalContributionRepository.add(dateWithinMonth(month), goalName, amount);
    }

    /**
     * Updates an existing allocation. Validated the same way as a new one,
     * except the allocation's own current amount is added back to the
     * available leftover first (if it was counted in this month at all) so
     * editing it isn't blocked by the allocation it's replacing.
     */
    public void updateContribution(long id, LocalDate date, String goalName, BigDecimal amount, YearMonth month) {
        GoalContribution existing = findContribution(id);
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Allocation amount must be positive.");
        }
        BigDecimal availableExcludingThis = availableLeftover(month);
        if (YearMonth.from(existing.getDate()).equals(month)) {
            availableExcludingThis = availableExcludingThis.add(existing.getAmount());
        }
        if (amount.compareTo(availableExcludingThis) > 0) {
            throw new IllegalArgumentException("Allocation exceeds available leftover.");
        }
        goalContributionRepository.update(id, date, goalName, amount);
    }

    public void deleteContribution(long id) {
        goalContributionRepository.remove(id);
    }

    private GoalContribution findContribution(long id) {
        return goalContributionRepository.findAll().stream()
                .filter(c -> c.getId() == id)
                .findFirst()
                .orElseThrow(() -> new IllegalArgumentException("No such allocation."));
    }

    /**
     * Today's date if it falls within the given month, else the 1st of that
     * month — so allocating into a past/future month (not "now") doesn't
     * silently record a contribution date outside the month it's meant to
     * count toward.
     */
    private LocalDate dateWithinMonth(YearMonth month) {
        LocalDate today = LocalDate.now();
        return YearMonth.from(today).equals(month) ? today : month.atDay(1);
    }

    public static class GoalProgress {
        private final SavingsGoal goal;
        private final BigDecimal savedAmount;

        public GoalProgress(SavingsGoal goal, BigDecimal savedAmount) {
            this.goal = goal;
            this.savedAmount = savedAmount;
        }

        public SavingsGoal getGoal() {
            return goal;
        }

        public BigDecimal getSavedAmount() {
            return savedAmount;
        }

        public double getPercentComplete() {
            BigDecimal target = goal.getTargetAmount();
            if (target.signum() <= 0) {
                return 0.0;
            }
            return savedAmount.divide(target, 4, RoundingMode.HALF_UP).doubleValue();
        }
    }
}

package com.example.finance;

import javafx.beans.property.SimpleObjectProperty;
import javafx.beans.property.SimpleStringProperty;
import javafx.collections.FXCollections;
import javafx.collections.ObservableList;
import javafx.geometry.Insets;
import javafx.scene.control.Button;
import javafx.scene.control.ComboBox;
import javafx.scene.control.DatePicker;
import javafx.scene.control.Label;
import javafx.scene.control.Separator;
import javafx.scene.control.Tab;
import javafx.scene.control.TableColumn;
import javafx.scene.control.TableView;
import javafx.scene.control.TextField;
import javafx.scene.layout.FlowPane;
import javafx.scene.layout.VBox;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;

/**
 * Create/edit/delete savings goals, with a table of each goal's saved
 * amount and progress, plus create/edit/delete for the individual leftover
 * allocations that make up those saved amounts.
 */
public class SavingsGoalsView {

    private final SavingsGoalRepository savingsGoalRepository;
    private final GoalContributionRepository goalContributionRepository;
    private final SavingsGoalService savingsGoalService;
    private final CategoryRepository categoryRepository;
    private final YearMonth month;

    private final ObservableList<SavingsGoal> goalOptions = FXCollections.observableArrayList();
    private final ObservableList<Category> categoryOptions = FXCollections.observableArrayList();
    private final ObservableList<SavingsGoalService.GoalProgress> rows = FXCollections.observableArrayList();
    private final ObservableList<GoalContribution> contributionRows = FXCollections.observableArrayList();
    private final Label leftoverLabel = new Label();

    public SavingsGoalsView(SavingsGoalRepository savingsGoalRepository,
                             GoalContributionRepository goalContributionRepository,
                             SavingsGoalService savingsGoalService,
                             CategoryRepository categoryRepository) {
        this(savingsGoalRepository, goalContributionRepository, savingsGoalService, categoryRepository,
                YearMonth.now());
    }

    public SavingsGoalsView(SavingsGoalRepository savingsGoalRepository,
                             GoalContributionRepository goalContributionRepository,
                             SavingsGoalService savingsGoalService,
                             CategoryRepository categoryRepository, YearMonth month) {
        this.savingsGoalRepository = savingsGoalRepository;
        this.goalContributionRepository = goalContributionRepository;
        this.savingsGoalService = savingsGoalService;
        this.categoryRepository = categoryRepository;
        this.month = month;
        leftoverLabel.setWrapText(true);
        refresh();
    }

    public Tab asTab() {
        Tab tab = new Tab("Savings Goals", buildContent());
        tab.setClosable(false);
        return tab;
    }

    public void refresh() {
        goalOptions.setAll(savingsGoalRepository.findAll());
        categoryOptions.setAll(categoryRepository.findAll());
        rows.setAll(savingsGoalService.goalProgress());
        contributionRows.setAll(goalContributionRepository.findAll());
        leftoverLabel.setText("Available leftover this month: " + savingsGoalService.availableLeftover(month));
    }

    private VBox buildContent() {
        VBox root = new VBox(12, buildGoalManagement(), new Separator(), leftoverLabel, buildAllocationManagement());
        root.setPadding(new Insets(12));
        return root;
    }

    private VBox buildGoalManagement() {
        TextField nameField = new TextField();
        nameField.setPromptText("Goal name");
        TextField targetField = new TextField();
        targetField.setPromptText("Target amount");
        DatePicker targetDatePicker = new DatePicker();
        targetDatePicker.setPromptText("Target date (optional)");
        ComboBox<Category> categoryBox = new ComboBox<>(categoryOptions);
        categoryBox.setPromptText("Category");
        Label status = new Label();
        status.setWrapText(true);

        TableView<SavingsGoalService.GoalProgress> table = buildGoalTable();

        Button saveButton = new Button("Add goal");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                SavingsGoal goal = newSelection.getGoal();
                nameField.setText(goal.getName());
                targetField.setText(goal.getTargetAmount().toString());
                targetDatePicker.setValue(goal.getTargetDate().orElse(null));
                categoryOptions.stream()
                        .filter(c -> c.getName().equals(goal.getCategoryName()))
                        .findFirst()
                        .ifPresent(categoryBox::setValue);
                saveButton.setText("Update goal");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Add goal");
                deleteButton.setDisable(true);
                categoryBox.setValue(null);
            }
        });

        saveButton.setOnAction(e -> {
            String name = nameField.getText().trim();
            if (name.isEmpty()) {
                status.setText("Goal name is required.");
                return;
            }
            Category category = categoryBox.getValue();
            if (category == null) {
                status.setText("Category is required.");
                return;
            }
            try {
                BigDecimal target = new BigDecimal(targetField.getText().trim());
                SavingsGoalService.GoalProgress selected = table.getSelectionModel().getSelectedItem();
                SavingsGoal updated = new SavingsGoal(name, target, targetDatePicker.getValue(), category.getName());
                if (selected == null) {
                    savingsGoalService.addGoal(updated);
                    status.setText("Added goal \"" + name + "\".");
                } else {
                    savingsGoalService.updateGoal(selected.getGoal().getName(), updated);
                    status.setText("Updated goal \"" + name + "\".");
                }
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                targetDatePicker.setValue(null);
                categoryBox.setValue(null);
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Target amount must be a number.");
            } catch (IllegalArgumentException ex) {
                status.setText(ex.getMessage());
            }
        });

        deleteButton.setOnAction(e -> {
            SavingsGoalService.GoalProgress selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            try {
                savingsGoalService.deleteGoal(selected.getGoal().getName());
                table.getSelectionModel().clearSelection();
                nameField.clear();
                targetField.clear();
                targetDatePicker.setValue(null);
                categoryBox.setValue(null);
                status.setText("Deleted goal \"" + selected.getGoal().getName() + "\".");
                refresh();
            } catch (IllegalStateException ex) {
                status.setText(ex.getMessage());
            }
        });

        FlowPane form = new FlowPane(8, 8, new Label("Goal:"), nameField, targetField, targetDatePicker, categoryBox,
                saveButton, deleteButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private VBox buildAllocationManagement() {
        ComboBox<SavingsGoal> goalBox = new ComboBox<>(goalOptions);
        DatePicker datePicker = new DatePicker(LocalDate.now());
        TextField amountField = new TextField();
        amountField.setPromptText("Amount");
        Label status = new Label();
        status.setWrapText(true);

        TableView<GoalContribution> table = buildContributionsTable();

        Button saveButton = new Button("Allocate to goal");
        Button deleteButton = new Button("Delete selected");
        deleteButton.setDisable(true);

        table.getSelectionModel().selectedItemProperty().addListener((obs, oldSelection, newSelection) -> {
            if (newSelection != null) {
                goalOptions.stream()
                        .filter(g -> g.getName().equals(newSelection.getGoalName()))
                        .findFirst()
                        .ifPresent(goalBox::setValue);
                datePicker.setValue(newSelection.getDate());
                amountField.setText(newSelection.getAmount().toString());
                saveButton.setText("Update allocation");
                deleteButton.setDisable(false);
            } else {
                saveButton.setText("Allocate to goal");
                deleteButton.setDisable(true);
            }
        });

        saveButton.setOnAction(e -> {
            SavingsGoal goal = goalBox.getValue();
            LocalDate date = datePicker.getValue();
            if (goal == null || date == null) {
                status.setText("Choose a goal and date.");
                return;
            }
            try {
                BigDecimal amount = new BigDecimal(amountField.getText().trim());
                GoalContribution selected = table.getSelectionModel().getSelectedItem();
                if (selected == null) {
                    savingsGoalService.allocateLeftoverToGoal(goal.getName(), amount, month);
                    status.setText("Allocated " + amount + " to \"" + goal.getName() + "\".");
                } else {
                    savingsGoalService.updateContribution(selected.getId(), date, goal.getName(), amount, month);
                    status.setText("Updated allocation.");
                }
                table.getSelectionModel().clearSelection();
                amountField.clear();
                refresh();
            } catch (NumberFormatException ex) {
                status.setText("Amount must be a number.");
            } catch (IllegalArgumentException ex) {
                status.setText(ex.getMessage());
            }
        });

        deleteButton.setOnAction(e -> {
            GoalContribution selected = table.getSelectionModel().getSelectedItem();
            if (selected == null) {
                return;
            }
            savingsGoalService.deleteContribution(selected.getId());
            table.getSelectionModel().clearSelection();
            amountField.clear();
            status.setText("Deleted allocation.");
            refresh();
        });

        FlowPane form = new FlowPane(8, 8, new Label("Allocate leftover:"), goalBox, datePicker, amountField,
                saveButton, deleteButton, status);
        VBox root = new VBox(6, form, table);
        TableSelectionUtil.clearSelectionOnClickOutside(root, table);
        return root;
    }

    private TableView<SavingsGoalService.GoalProgress> buildGoalTable() {
        TableView<SavingsGoalService.GoalProgress> table = new TableView<>(rows);

        TableColumn<SavingsGoalService.GoalProgress, String> nameCol = new TableColumn<>("Goal");
        nameCol.setCellValueFactory(cell -> new SimpleStringProperty(cell.getValue().getGoal().getName()));

        TableColumn<SavingsGoalService.GoalProgress, String> categoryCol = new TableColumn<>("Category");
