import java.time.LocalDate;
import java.time.YearMonth;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class SavingsGoalServiceTest {

    private record Fixture(SavingsGoalService service, TransactionRepository transactionRepository,
                            SavingsGoalRepository savingsGoalRepository, CategoryRepository categoryRepository,
                            GoalContributionRepository goalContributionRepository) {
    }

    private Fixture newFixture(Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        BudgetService budgetService = new BudgetService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);
        GoalContributionRepository goalContributionRepository = new GoalContributionRepository(dataPaths);
        SavingsGoalService service = new SavingsGoalService(
                savingsGoalRepository, goalContributionRepository, budgetService, categoryRepository);
        return new Fixture(service, transactionRepository, savingsGoalRepository, categoryRepository,
                goalContributionRepository);
    }

    @Test
    void allocationReducesAvailableLeftoverAndIncreasesGoalProgress(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        YearMonth august = YearMonth.of(2026, 8);
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("1000.00"), "paycheck");
        fixture.savingsGoalRepository().add(
                new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));

        assertEquals(new BigDecimal("1000.00"), fixture.service().availableLeftover(august));

        fixture.service().allocateLeftoverToGoal("Emergency fund", new BigDecimal("300.00"), august);

        assertEquals(new BigDecimal("700.00"), fixture.service().availableLeftover(august));
        assertEquals(new BigDecimal("300.00"), fixture.service().totalSaved("Emergency fund"));
    }

    @Test
    void rejectsAllocationThatExceedsAvailableLeftover(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        YearMonth august = YearMonth.of(2026, 8);
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("100.00"), "paycheck");
        fixture.savingsGoalRepository().add(
                new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));

        assertThrows(IllegalArgumentException.class, () ->
                fixture.service().allocateLeftoverToGoal("Emergency fund", new BigDecimal("100.01"), august));
    }

    @Test
    void rejectsNonPositiveAllocation(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        YearMonth august = YearMonth.of(2026, 8);

        assertThrows(IllegalArgumentException.class, () ->
                fixture.service().allocateLeftoverToGoal("Emergency fund", BigDecimal.ZERO, august));
    }

    @Test
    void updateGoalRenameCascadesToContributions(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));
        fixture.goalContributionRepository().add(LocalDate.of(2026, 8, 1), "Emergency fund", new BigDecimal("100.00"));

        fixture.service().updateGoal("Emergency fund",
                new SavingsGoal("Rainy day fund", new BigDecimal("600.00"), null, "Emergency fund"));

        assertEquals("Rainy day fund", fixture.savingsGoalRepository().findAll().get(0).getName());
        assertEquals(new BigDecimal("100.00"), fixture.service().totalSaved("Rainy day fund"));
        assertEquals(BigDecimal.ZERO.setScale(2), fixture.service().totalSaved("Emergency fund").setScale(2));
    }

    @Test
    void addGoalRejectsACategoryNameThatDoesNotExist(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);

        assertThrows(IllegalArgumentException.class, () -> fixture.service().addGoal(
                new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "No such category")));
    }

    @Test
    void updateGoalRejectsACategoryNameThatDoesNotExist(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));

        assertThrows(IllegalArgumentException.class, () -> fixture.service().updateGoal("Emergency fund",
                new SavingsGoal("Emergency fund", new BigDecimal("600.00"), null, "No such category")));
    }

    @Test
    void deleteGoalRemovesAGoalWithNoSavings(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));

        fixture.service().deleteGoal("Emergency fund");

        assertEquals(0, fixture.savingsGoalRepository().findAll().size());
    }

    @Test
    void deleteGoalRejectsAGoalThatAlreadyHasSavings(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));
        fixture.goalContributionRepository().add(LocalDate.of(2026, 8, 1), "Emergency fund", new BigDecimal("100.00"));

        assertThrows(IllegalStateException.class, () -> fixture.service().deleteGoal("Emergency fund"));
        assertEquals(1, fixture.savingsGoalRepository().findAll().size());
    }

    @Test
    void updateContributionChangesTheAmountWithoutDoubleCountingItsOwnOldAmount(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        YearMonth august = YearMonth.of(2026, 8);
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("1000.00"), "paycheck");
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));
        GoalContribution contribution = fixture.goalContributionRepository()
                .add(LocalDate.of(2026, 8, 5), "Emergency fund", new BigDecimal("300.00"));

        fixture.service().updateContribution(contribution.getId(), LocalDate.of(2026, 8, 5),
                "Emergency fund", new BigDecimal("400.00"), august);

        assertEquals(new BigDecimal("400.00"), fixture.service().totalSaved("Emergency fund"));
        assertEquals(new BigDecimal("600.00"), fixture.service().availableLeftover(august));
    }

    @Test
    void updateContributionRejectsAnIncreaseThatExceedsAvailableLeftover(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        YearMonth august = YearMonth.of(2026, 8);
        fixture.transactionRepository().add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("1000.00"), "paycheck");
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));
        GoalContribution contribution = fixture.goalContributionRepository()
                .add(LocalDate.of(2026, 8, 5), "Emergency fund", new BigDecimal("300.00"));

        assertThrows(IllegalArgumentException.class, () -> fixture.service().updateContribution(
                contribution.getId(), LocalDate.of(2026, 8, 5), "Emergency fund",
                new BigDecimal("1000.01"), august));
    }

    @Test
    void deleteContributionRemovesItAndReducesTotalSaved(@TempDir Path tempDir) {
        Fixture fixture = newFixture(tempDir);
        fixture.categoryRepository().add(new Category("Emergency fund", BigDecimal.ZERO));
        fixture.service().addGoal(new SavingsGoal("Emergency fund", new BigDecimal("500.00"), null, "Emergency fund"));
        GoalContribution contribution = fixture.goalContributionRepository()
                .add(LocalDate.of(2026, 8, 5), "Emergency fund", new BigDecimal("300.00"));

        fixture.service().deleteContribution(contribution.getId());

        assertEquals(BigDecimal.ZERO.setScale(2), fixture.service().totalSaved("Emergency fund").setScale(2));
        assertEquals(0, fixture.goalContributionRepository().findAll().size());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TransactionCsvImporterTest {

    private final TransactionCsvImporter importer = new TransactionCsvImporter();

    @Test
    void importsRowsWithStandardDateAndSignedAmountHeaders(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description,Category",
                "2026-08-01,2500.00,August paycheck,Salary",
                "2026-08-03,-64.32,Weekly shop,Groceries") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(2, result.successCount());
        assertEquals(0, result.errorCount());
        TransactionDraft income = result.rows().get(0);
        assertEquals(TransactionType.INCOME, income.type());
        assertEquals(new BigDecimal("2500.00"), income.amount());
        TransactionDraft expense = result.rows().get(1);
        assertEquals(TransactionType.EXPENSE, expense.type());
        assertEquals(new BigDecimal("64.32"), expense.amount());
    }

    @Test
    void resolvesTransactionDateHeaderAlias(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Transaction Date,Amount,Description",
                "2026-08-05,10.00,Coffee") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(1, result.successCount());
        assertEquals(LocalDate.of(2026, 8, 5), result.rows().get(0).date());
    }

    @Test
    void importsRowsWithDebitCreditColumnsInsteadOfAmount(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Description,Debit,Credit,Category",
                "2026-08-01,Paycheck,,2500.00,Salary",
                "2026-08-03,Groceries,64.32,,Groceries") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(2, result.successCount());
        assertEquals(TransactionType.INCOME, result.rows().get(0).type());
        assertEquals(new BigDecimal("2500.00"), result.rows().get(0).amount());
        assertEquals(TransactionType.EXPENSE, result.rows().get(1).type());
        assertEquals(new BigDecimal("64.32"), result.rows().get(1).amount());
    }

    @Test
    void defaultsCategoryToUncategorizedWhenColumnIsAbsent(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description",
                "2026-08-01,10.00,Coffee") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals("Uncategorized", result.rows().get(0).categoryName());
    }

    @Test
    void parsesBothIsoAndUsSlashDateFormatsInTheSameFile(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description",
                "2026-08-05,10.00,Coffee",
                "8/5/2026,20.00,Lunch") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(2, result.successCount());
        assertEquals(LocalDate.of(2026, 8, 5), result.rows().get(0).date());
        assertEquals(LocalDate.of(2026, 8, 5), result.rows().get(1).date());
    }

    @Test
    void handlesQuotedDescriptionsWithEmbeddedCommas(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description",
                "2026-08-01,10.00,\"Coffee Shop, Inc.\"") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(1, result.successCount());
        assertEquals("Coffee Shop, Inc.", result.rows().get(0).description());
    }

    @Test
    void skipsMalformedRowsWithoutLosingValidRowsInSameFile(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description",
                "2026-08-01,10.00,Good row",
                "not-a-date,10.00,Bad date",
                "2026-08-02,not-a-number,Bad amount",
                "2026-08-03,20.00,Another good row") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(2, result.successCount());
        assertEquals(2, result.errorCount());
        assertTrue(result.rows().stream().anyMatch(r -> r.description().equals("Good row")));
        assertTrue(result.rows().stream().anyMatch(r -> r.description().equals("Another good row")));
    }

    @Test
    void skipsRowWithBothDebitAndCreditFilled(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Description,Debit,Credit",
                "2026-08-01,Ambiguous,5.00,5.00") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(0, result.successCount());
        assertEquals(1, result.errorCount());
    }

    @Test
    void skipsZeroAmountRowAsAmbiguousSign(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Amount,Description",
                "2026-08-01,0.00,Zero") + "\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(0, result.successCount());
        assertEquals(1, result.errorCount());
    }

    @Test
    void throwsWhenDateColumnIsMissingEntirely(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Amount,Description",
                "10.00,Coffee") + "\n");

        assertThrows(TransactionCsvImportException.class, () -> importer.importFile(file));
    }

    @Test
    void throwsWhenNeitherAmountNorDebitCreditColumnsArePresent(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, String.join("\n",
                "Date,Description",
                "2026-08-01,Coffee") + "\n");

        assertThrows(TransactionCsvImportException.class, () -> importer.importFile(file));
    }

    @Test
    void throwsOnCompletelyEmptyFile(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, "");

        assertThrows(TransactionCsvImportException.class, () -> importer.importFile(file));
    }

    @Test
    void returnsEmptyResultForHeaderOnlyFileWithNoDataRows(@TempDir Path tempDir) throws Exception {
        Path file = tempDir.resolve("import.csv");
        Files.writeString(file, "Date,Amount,Description\n");

        TransactionCsvImporter.ImportResult result = importer.importFile(file);

        assertEquals(List.of(), result.rows());
        assertEquals(List.of(), result.errors());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class TransactionRepositoryTest {

    @Test
    void savesAndReloadsTransactions(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);

        TransactionRepository repository = new TransactionRepository(dataPaths);
        repository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Salary",
                new BigDecimal("2500.00"), "August paycheck");
        repository.add(LocalDate.of(2026, 8, 3), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("64.32"), "Weekly shop");

        TransactionRepository reloaded = new TransactionRepository(dataPaths);
        List<Transaction> transactions = reloaded.findAll();

        assertEquals(2, transactions.size());
        assertEquals("Salary", transactions.get(0).getCategoryName());
        assertEquals(new BigDecimal("2500.00"), transactions.get(0).getAmount());
        assertEquals(TransactionType.EXPENSE, transactions.get(1).getType());
        assertEquals("Weekly shop", transactions.get(1).getDescription());
    }

    @Test
    void skipsMalformedLinesWithoutLosingOtherEntries(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.transactionsFile(), String.join("\n",
                "# id|date|type|categoryName|amount|description",
                "1|2026-08-01|INCOME|Salary|2500.00|August paycheck",
                "not-a-valid-line",
                "2|2026-08-03|EXPENSE|Groceries|64.32|Weekly shop") + "\n");

        TransactionRepository repository = new TransactionRepository(dataPaths);
        List<Transaction> transactions = repository.findAll();

        assertEquals(2, transactions.size());
        assertTrue(transactions.stream().anyMatch(t -> t.getCategoryName().equals("Salary")));
        assertTrue(transactions.stream().anyMatch(t -> t.getCategoryName().equals("Groceries")));
    }

    @Test
    void continuesIdSequenceAfterReload(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        TransactionRepository repository = new TransactionRepository(dataPaths);
        repository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("10.00"), "first");

        TransactionRepository reloaded = new TransactionRepository(dataPaths);
        Transaction second = reloaded.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("20.00"), "second");

        assertEquals(2, second.getId());
    }

    @Test
    void addAllAssignsSequentialIdsAndPersistsInOneCall(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        TransactionRepository repository = new TransactionRepository(dataPaths);
        repository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("10.00"), "first");

        List<Transaction> added = repository.addAll(List.of(
                new TransactionDraft(LocalDate.of(2026, 8, 2), TransactionType.INCOME, "Salary",
                        new BigDecimal("2500.00"), "August paycheck"),
                new TransactionDraft(LocalDate.of(2026, 8, 3), TransactionType.EXPENSE, "Dining",
                        new BigDecimal("15.00"), "Lunch")));

        assertEquals(2, added.get(0).getId());
        assertEquals(3, added.get(1).getId());

        TransactionRepository reloaded = new TransactionRepository(dataPaths);
        List<Transaction> transactions = reloaded.findAll();
        assertEquals(3, transactions.size());
        assertTrue(transactions.stream().anyMatch(t -> t.getDescription().equals("August paycheck")));
        assertTrue(transactions.stream().anyMatch(t -> t.getDescription().equals("Lunch")));
    }

    @Test
    void updateReplacesTheMatchingTransaction(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        TransactionRepository repository = new TransactionRepository(dataPaths);
        Transaction original = repository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("10.00"), "first");

        repository.update(original.getId(), LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Dining",
                new BigDecimal("15.00"), "corrected");

        List<Transaction> transactions = repository.findAll();
        assertEquals(1, transactions.size());
        assertEquals("Dining", transactions.get(0).getCategoryName());
        assertEquals(new BigDecimal("15.00"), transactions.get(0).getAmount());
        assertEquals("corrected", transactions.get(0).getDescription());
    }

    @Test
    void removeDeletesTheMatchingTransaction(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        TransactionRepository repository = new TransactionRepository(dataPaths);
        Transaction toDelete = repository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("10.00"), "first");
        repository.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("20.00"), "second");

        repository.remove(toDelete.getId());

        List<Transaction> transactions = repository.findAll();
        assertEquals(1, transactions.size());
        assertEquals("second", transactions.get(0).getDescription());
    }

    @Test
    void renameCategoryUpdatesAllMatchingTransactions(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        TransactionRepository repository = new TransactionRepository(dataPaths);
        repository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("10.00"), "first");
        repository.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Dining",
                new BigDecimal("20.00"), "unrelated");

        repository.renameCategory("Groceries", "Food");

        List<Transaction> transactions = repository.findAll();
        assertTrue(transactions.stream().anyMatch(t -> t.getCategoryName().equals("Food")));
        assertTrue(transactions.stream().anyMatch(t -> t.getCategoryName().equals("Dining")));
        assertTrue(transactions.stream().noneMatch(t -> t.getCategoryName().equals("Groceries")));
    }
}

