package com.example.finance;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.EnumMap;
import java.util.List;
import java.util.Map;

/**
 * For a given month, compares the % share of total target budget allocated
 * to each Priority tier against the % share of total actual spend that
 * landed there. Consumes BudgetService.categoryTotals(month) so income-only
 * categories are excluded the same way every other spending view excludes
 * them, and so money tagged directly to a goal/obligation already rolls up
 * into its assigned category's actual before this ever sees it.
 */
public class PriorityAlignmentService {

    /** Target/actual shares within this many percentage points count as matched. */
    public static final BigDecimal TOLERANCE_PERCENTAGE_POINTS = new BigDecimal("1.00");

    private static final BigDecimal ONE_HUNDRED = new BigDecimal("100");
    private static final int PERCENT_SCALE = 2;

    private final BudgetService budgetService;

    public PriorityAlignmentService(BudgetService budgetService) {
        this.budgetService = budgetService;
    }

    public PriorityAlignmentReport alignmentForMonth(YearMonth month) {
        List<BudgetService.CategoryTotal> totals = budgetService.categoryTotals(month).stream()
                .filter(t -> !t.isIncomeOnly())
                .toList();

        Map<Priority, BigDecimal> targetByTier = new EnumMap<>(Priority.class);
        Map<Priority, BigDecimal> actualByTier = new EnumMap<>(Priority.class);
        for (Priority priority : Priority.values()) {
            targetByTier.put(priority, BigDecimal.ZERO);
            actualByTier.put(priority, BigDecimal.ZERO);
        }
        BigDecimal grandTarget = BigDecimal.ZERO;
        BigDecimal grandActual = BigDecimal.ZERO;
        for (BudgetService.CategoryTotal total : totals) {
            Priority priority = total.getCategory().getPriority();
            targetByTier.merge(priority, total.getCategory().getMonthlyTarget(), BigDecimal::add);
            actualByTier.merge(priority, total.getActual(), BigDecimal::add);
            grandTarget = grandTarget.add(total.getCategory().getMonthlyTarget());
            grandActual = grandActual.add(total.getActual());
        }

        List<TierAlignment> tiers = new ArrayList<>();
        for (Priority priority : Priority.values()) {
            BigDecimal targetTotal = targetByTier.get(priority);
            BigDecimal actualTotal = actualByTier.get(priority);
            tiers.add(new TierAlignment(priority, targetTotal, actualTotal,
                    sharePercent(targetTotal, grandTarget), sharePercent(actualTotal, grandActual)));
        }
        return new PriorityAlignmentReport(tiers);
    }

    private static BigDecimal sharePercent(BigDecimal tierTotal, BigDecimal grandTotal) {
        if (grandTotal.signum() == 0) {
            return BigDecimal.ZERO.setScale(PERCENT_SCALE);
        }
        return tierTotal.multiply(ONE_HUNDRED).divide(grandTotal, PERCENT_SCALE, RoundingMode.HALF_UP);
    }

    public enum AlignmentVerdict {
        UNDER_INDEXED, MATCHED, OVER_INDEXED
    }

    public static class TierAlignment {
        private final Priority priority;
        private final BigDecimal targetTotal;
        private final BigDecimal actualTotal;
        private final BigDecimal targetSharePercent;
        private final BigDecimal actualSharePercent;

        public TierAlignment(Priority priority, BigDecimal targetTotal, BigDecimal actualTotal,
                              BigDecimal targetSharePercent, BigDecimal actualSharePercent) {
            this.priority = priority;
            this.targetTotal = targetTotal;
            this.actualTotal = actualTotal;
            this.targetSharePercent = targetSharePercent;
            this.actualSharePercent = actualSharePercent;
        }

        public Priority getPriority() {
            return priority;
        }

        public BigDecimal getTargetTotal() {
            return targetTotal;
        }

        public BigDecimal getActualTotal() {
            return actualTotal;
        }

        public BigDecimal getTargetSharePercent() {
            return targetSharePercent;
        }

        public BigDecimal getActualSharePercent() {
            return actualSharePercent;
        }

        public BigDecimal getSharePercentDifference() {
            return actualSharePercent.subtract(targetSharePercent);
        }

        public AlignmentVerdict getVerdict() {
            BigDecimal difference = getSharePercentDifference();
            if (difference.abs().compareTo(TOLERANCE_PERCENTAGE_POINTS) <= 0) {
                return AlignmentVerdict.MATCHED;
            }
            return difference.signum() > 0 ? AlignmentVerdict.OVER_INDEXED : AlignmentVerdict.UNDER_INDEXED;
        }
    }

    public static class PriorityAlignmentReport {
        private final List<TierAlignment> tiers;

        public PriorityAlignmentReport(List<TierAlignment> tiers) {
            this.tiers = tiers;
        }

        public List<TierAlignment> getTiers() {
            return tiers;
        }
    }
}

