package com.example.finance;

import org.junit.jupiter.api.Test;

import java.math.BigDecimal;

import static org.junit.jupiter.api.Assertions.assertEquals;

class CategoryTest {

    @Test
    void twoArgConstructorDefaultsPriorityToDiscretionary() {
        Category category = new Category("Groceries", new BigDecimal("100.00"));
        assertEquals(Priority.DISCRETIONARY, category.getPriority());
    }

    @Test
    void threeArgConstructorStoresGivenPriority() {
