class PriorityAlignmentServiceTest {

    private PriorityAlignmentService newService(CategoryRepository categoryRepository,
                                                  TransactionRepository transactionRepository,
                                                  SavingsGoalRepository savingsGoalRepository,
                                                  RecurringObligationRepository recurringObligationRepository) {
        BudgetService budgetService = new BudgetService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);
        return new PriorityAlignmentService(budgetService);
    }

    @Test
    void alignmentForMonthComputesTargetAndActualSharesAcrossAllThreeTiers(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Rent", new BigDecimal("600.00"), Priority.ESSENTIAL));
        categoryRepository.add(new Category("Insurance", new BigDecimal("300.00"), Priority.IMPORTANT));
        categoryRepository.add(new Category("Dining out", new BigDecimal("100.00"), Priority.DISCRETIONARY));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
                new BigDecimal("600.00"), "rent");
        transactionRepository.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Insurance",
                new BigDecimal("300.00"), "insurance");
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Dining out",
                new BigDecimal("100.00"), "dinner");

        PriorityAlignmentService.PriorityAlignmentReport report = service.alignmentForMonth(august);

        List<PriorityAlignmentService.TierAlignment> tiers = report.getTiers();
        assertEquals(3, tiers.size());
        PriorityAlignmentService.TierAlignment essential = tiers.get(0);
        assertEquals(Priority.ESSENTIAL, essential.getPriority());
        assertEquals(new BigDecimal("600.00"), essential.getTargetTotal());
        assertEquals(new BigDecimal("600.00"), essential.getActualTotal());
        assertEquals(new BigDecimal("60.00"), essential.getTargetSharePercent());
        assertEquals(new BigDecimal("60.00"), essential.getActualSharePercent());
        assertEquals(PriorityAlignmentService.AlignmentVerdict.MATCHED, essential.getVerdict());
    }

    @Test
    void allThreeTiersAreAlwaysPresentEvenWhenATierHasNoCategories(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Rent", new BigDecimal("600.00"), Priority.ESSENTIAL));
        categoryRepository.add(new Category("Dining out", new BigDecimal("100.00"), Priority.DISCRETIONARY));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
                new BigDecimal("600.00"), "rent");

        PriorityAlignmentService.TierAlignment important = service.alignmentForMonth(august).getTiers().stream()
                .filter(t -> t.getPriority() == Priority.IMPORTANT).findFirst().orElseThrow();

        assertEquals(BigDecimal.ZERO, important.getTargetTotal());
        assertEquals(BigDecimal.ZERO, important.getActualTotal());
        assertEquals(new BigDecimal("0.00"), important.getTargetSharePercent());
        assertEquals(new BigDecimal("0.00"), important.getActualSharePercent());
    }

    @Test
    void sharesDefaultToZeroWhenTotalTargetIsZeroInsteadOfDividingByZero(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        PriorityAlignmentService.PriorityAlignmentReport report = service.alignmentForMonth(YearMonth.of(2026, 8));

        assertTrue(report.getTiers().stream()
                .allMatch(t -> t.getTargetSharePercent().equals(new BigDecimal("0.00"))
                        && t.getActualSharePercent().equals(new BigDecimal("0.00"))));
    }

    @Test
    void incomeOnlyCategoriesAreExcludedFromTierTotals(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Paycheck", new BigDecimal("1000.00"), Priority.ESSENTIAL));
        categoryRepository.add(new Category("Groceries", new BigDecimal("200.00"), Priority.DISCRETIONARY));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Paycheck",
                new BigDecimal("1000.00"), "august paycheck");
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("200.00"), "shop");

        PriorityAlignmentService.PriorityAlignmentReport report = service.alignmentForMonth(august);

        PriorityAlignmentService.TierAlignment essential = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.ESSENTIAL).findFirst().orElseThrow();
        PriorityAlignmentService.TierAlignment discretionary = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.DISCRETIONARY).findFirst().orElseThrow();

        assertEquals(BigDecimal.ZERO, essential.getTargetTotal());
        assertEquals(BigDecimal.ZERO, essential.getActualTotal());
        assertEquals(new BigDecimal("200.00"), discretionary.getTargetTotal());
        assertEquals(new BigDecimal("200.00"), discretionary.getActualTotal());
        assertEquals(new BigDecimal("100.00"), discretionary.getTargetSharePercent());
        assertEquals(new BigDecimal("100.00"), discretionary.getActualSharePercent());
    }

    @Test
    void sharePercentRoundsToTwoDecimalPlacesUsingHalfUp(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("A", new BigDecimal("50.00"), Priority.ESSENTIAL));
        categoryRepository.add(new Category("B", new BigDecimal("25.00"), Priority.DISCRETIONARY));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        PriorityAlignmentService.PriorityAlignmentReport report = service.alignmentForMonth(YearMonth.of(2026, 8));

        PriorityAlignmentService.TierAlignment essential = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.ESSENTIAL).findFirst().orElseThrow();
        PriorityAlignmentService.TierAlignment discretionary = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.DISCRETIONARY).findFirst().orElseThrow();

        assertEquals(new BigDecimal("66.67"), essential.getTargetSharePercent());
        assertEquals(new BigDecimal("33.33"), discretionary.getTargetSharePercent());
    }

    @Test
    void verdictIsMatchedWhenShareDifferenceIsExactlyAtTheToleranceBoundary() {
        PriorityAlignmentService.TierAlignment tier = new PriorityAlignmentService.TierAlignment(
                Priority.ESSENTIAL, new BigDecimal("500.00"), new BigDecimal("510.00"),
                new BigDecimal("50.00"), new BigDecimal("51.00"));
        assertEquals(PriorityAlignmentService.AlignmentVerdict.MATCHED, tier.getVerdict());
    }

    @Test
    void verdictIsOverIndexedJustBeyondTheToleranceBoundary() {
        PriorityAlignmentService.TierAlignment tier = new PriorityAlignmentService.TierAlignment(
                Priority.DISCRETIONARY, new BigDecimal("500.00"), new BigDecimal("510.10"),
                new BigDecimal("50.00"), new BigDecimal("51.01"));
        assertEquals(PriorityAlignmentService.AlignmentVerdict.OVER_INDEXED, tier.getVerdict());
        assertFalse(tier.getVerdict() == PriorityAlignmentService.AlignmentVerdict.MATCHED);
    }

    @Test
    void verdictIsUnderIndexedJustBeyondTheToleranceBoundary() {
        PriorityAlignmentService.TierAlignment tier = new PriorityAlignmentService.TierAlignment(
                Priority.ESSENTIAL, new BigDecimal("500.00"), new BigDecimal("489.90"),
                new BigDecimal("50.00"), new BigDecimal("48.99"));
        assertEquals(PriorityAlignmentService.AlignmentVerdict.UNDER_INDEXED, tier.getVerdict());
    }
}

