        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
                new BigDecimal("800.00"), "august rent");
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Entertainment",
                new BigDecimal("400.00"), "overspent on fun");

        PriorityAlignmentService.PriorityAlignmentReport report = monthSummaryService.summarizePriorityAlignment(august);

        PriorityAlignmentService.TierAlignment essential = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.ESSENTIAL).findFirst().orElseThrow();
        PriorityAlignmentService.TierAlignment discretionary = report.getTiers().stream()
                .filter(t -> t.getPriority() == Priority.DISCRETIONARY).findFirst().orElseThrow();

        assertEquals(new BigDecimal("80.00"), essential.getTargetSharePercent());
        assertEquals(new BigDecimal("66.67"), essential.getActualSharePercent());
        assertEquals(PriorityAlignmentService.AlignmentVerdict.UNDER_INDEXED, essential.getVerdict());

        assertEquals(new BigDecimal("20.00"), discretionary.getTargetSharePercent());
        assertEquals(new BigDecimal("33.33"), discretionary.getActualSharePercent());
        assertEquals(PriorityAlignmentService.AlignmentVerdict.OVER_INDEXED, discretionary.getVerdict());
    }
}

