}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

class CategoryRepositoryTest {

    @Test
    void addPersistsAndReloadsThePriorityColumn(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository repository = new CategoryRepository(dataPaths);
        repository.add(new Category("Rent", new BigDecimal("800.00"), 1));

        CategoryRepository reloaded = new CategoryRepository(dataPaths);
        List<Category> categories = reloaded.findAll();

        assertEquals(1, categories.size());
        assertEquals(1, categories.get(0).getPriority().orElseThrow());
    }

    @Test
    void updateReplacesTheMatchingCategoryIncludingPriority(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository repository = new CategoryRepository(dataPaths);
        repository.add(new Category("Streaming", new BigDecimal("15.00"), 3));

        repository.update("Streaming", new Category("Streaming", new BigDecimal("15.00"), 2));

        CategoryRepository reloaded = new CategoryRepository(dataPaths);
        assertEquals(2, reloaded.findAll().get(0).getPriority().orElseThrow());
    }

    @Test
    void loadsOlderLinesThatStillHaveOnlyNameAndMonthlyTargetColumns(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.categoriesFile(), String.join("\n",
                "# name|monthlyTarget",
                "Groceries|400.00") + "\n");

        CategoryRepository repository = new CategoryRepository(dataPaths);
        List<Category> categories = repository.findAll();

        assertEquals(1, categories.size());
        assertEquals(new BigDecimal("400.00"), categories.get(0).getMonthlyTarget());
        assertTrue(categories.get(0).getPriority().isEmpty());
    }

    @Test
    void loadsLinesWithABlankPriorityColumnAsUnprioritized(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.categoriesFile(), String.join("\n",
                "# name|monthlyTarget|priority",
                "Groceries|400.00|") + "\n");

        CategoryRepository repository = new CategoryRepository(dataPaths);
        List<Category> categories = repository.findAll();

        assertEquals(1, categories.size());
        assertTrue(categories.get(0).getPriority().isEmpty());
    }

    @Test
    void skipsLinesWithAnInvalidPriorityValueConsistentWithOtherMalformedLines(@TempDir Path tempDir) throws Exception {
        DataPaths dataPaths = new DataPaths(tempDir);
        Files.createDirectories(tempDir);
        Files.writeString(dataPaths.categoriesFile(), String.join("\n",
                "# name|monthlyTarget|priority",
                "Groceries|400.00|NOT_A_NUMBER") + "\n");

        CategoryRepository repository = new CategoryRepository(dataPaths);

        assertTrue(repository.findAll().isEmpty());
    }
}

package com.example.finance;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.math.BigDecimal;
import java.nio.file.Path;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class PriorityAlignmentServiceTest {

    private PriorityAlignmentService newService(CategoryRepository categoryRepository,
                                                  TransactionRepository transactionRepository,
                                                  SavingsGoalRepository savingsGoalRepository,
                                                  RecurringObligationRepository recurringObligationRepository) {
        BudgetService budgetService = new BudgetService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);
        return new PriorityAlignmentService(budgetService);
    }

    @Test
    void rankingIsSortedByPriorityAscendingWithSpendRankComputedAmongTheSameSet(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Rent", new BigDecimal("800.00"), 1));
        categoryRepository.add(new Category("Groceries", new BigDecimal("300.00"), 2));
        categoryRepository.add(new Category("Entertainment", new BigDecimal("50.00"), 3));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
                new BigDecimal("800.00"), "rent");
        transactionRepository.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Groceries",
                new BigDecimal("100.00"), "groceries");
        // Entertainment outspends Groceries this month, so it should rank
        // #2 by spend even though it's priority #3.
        transactionRepository.add(LocalDate.of(2026, 8, 5), TransactionType.EXPENSE, "Entertainment",
                new BigDecimal("250.00"), "concert");

        List<PriorityAlignmentService.PriorityRankRow> rows = service.rankingForMonth(august);

        assertEquals(3, rows.size());
        assertEquals("Rent", rows.get(0).getCategory().getName());
        assertEquals(1, rows.get(0).getPriorityRank());
        assertEquals(1, rows.get(0).getSpendRank());
        assertTrue(rows.get(0).matchesSpendRank());

        assertEquals("Groceries", rows.get(1).getCategory().getName());
        assertEquals(2, rows.get(1).getPriorityRank());
        assertEquals(3, rows.get(1).getSpendRank());
        assertFalse(rows.get(1).matchesSpendRank());

        assertEquals("Entertainment", rows.get(2).getCategory().getName());
        assertEquals(3, rows.get(2).getPriorityRank());
        assertEquals(2, rows.get(2).getSpendRank());
        assertFalse(rows.get(2).matchesSpendRank());
    }

    @Test
    void unprioritizedCategoriesAreExcludedEntirelyAndDoNotAffectSpendRank(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Rent", new BigDecimal("800.00"), 1));
        categoryRepository.add(new Category("Miscellaneous", new BigDecimal("50.00")));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Rent",
                new BigDecimal("800.00"), "rent");
        // Outspends Rent, but has no priority set, so it must not appear
        // and must not push Rent's spend rank down.
        transactionRepository.add(LocalDate.of(2026, 8, 2), TransactionType.EXPENSE, "Miscellaneous",
                new BigDecimal("5000.00"), "big purchase");

        List<PriorityAlignmentService.PriorityRankRow> rows = service.rankingForMonth(august);

        assertEquals(1, rows.size());
        assertEquals("Rent", rows.get(0).getCategory().getName());
        assertEquals(1, rows.get(0).getSpendRank());
    }

    @Test
    void incomeOnlyCategoriesAreExcludedEvenIfPrioritized(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Paycheck", new BigDecimal("1000.00"), 1));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.INCOME, "Paycheck",
                new BigDecimal("1000.00"), "august paycheck");

        List<PriorityAlignmentService.PriorityRankRow> rows = service.rankingForMonth(YearMonth.of(2026, 8));

        assertTrue(rows.isEmpty());
    }

    @Test
    void tiesInPriorityOrSpendAreBrokenDeterministicallyByName(@TempDir Path tempDir) {
        DataPaths dataPaths = new DataPaths(tempDir);
        CategoryRepository categoryRepository = new CategoryRepository(dataPaths);
        TransactionRepository transactionRepository = new TransactionRepository(dataPaths);
        SavingsGoalRepository savingsGoalRepository = new SavingsGoalRepository(dataPaths);
        RecurringObligationRepository recurringObligationRepository = new RecurringObligationRepository(dataPaths);
        categoryRepository.add(new Category("Beta", new BigDecimal("100.00"), 1));
        categoryRepository.add(new Category("Alpha", new BigDecimal("100.00"), 1));
        PriorityAlignmentService service = newService(
                categoryRepository, transactionRepository, savingsGoalRepository, recurringObligationRepository);

        YearMonth august = YearMonth.of(2026, 8);
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Beta",
                new BigDecimal("50.00"), "beta spend");
        transactionRepository.add(LocalDate.of(2026, 8, 1), TransactionType.EXPENSE, "Alpha",
                new BigDecimal("50.00"), "alpha spend");

        List<PriorityAlignmentService.PriorityRankRow> rows = service.rankingForMonth(august);

        assertEquals("Alpha", rows.get(0).getCategory().getName());
